\label{Corollary irrational szem mobius}
Let $\theta_1,\dots,\theta _s \in \mathbb{R}$ be distinct irrational numbers, let $N$ be an integer parameter, and let $f_1,f_2,\dots,f_{s+1}: \{ 1,\dots,N\} \longrightarrow [-1,1]$ be arbitrary $1$-bounded functions. Then 
\begin{equation}
\frac{1}{N^2} \sum\limits_{\substack{x,d \in \mathbb{Z} \\ 1 \leqslant x \leqslant N}} \mu(x) f_1(x+d)\Big (\prod\limits_{i=2}^{s+1} f_i([x + \theta_{i-1} d]) \Big ) = o(1)
\end{equation}
\noindent as $N \rightarrow \infty$, where $\mu$ denotes the M\"{o}bius function and $[x] : = \lfloor x + \frac{1}{2}\rfloor$ is the nearest integer to $x$. The $o(1)$ error term may depend on the numbers $\theta_1,\dots,\theta_s$ but is independent of the choice of functions $f_1,\dots,f_{s+1}$.\\

\begin{equation}
\frac{1}{N^2} \sum\limits_{\substack{x,d \in \mathbb{Z} \\ 1 \leqslant x \leqslant N}} \mu(x) f_1(x+d)\Big (\prod\limits_{i=2}^{s+1} f_i([x + \theta_{i-1} d]) \Big ) = o(1)
\end{equation}

For example, if $A$ is the set of squares, it was shown by Davenport and Heilbronn in \cite{DaHe46} that there are infinitely many solutions to (\ref{the general inequality}) for $m=1$ and $d=5$, i.e. infinitely many solutions to 
\begin{equation}
\label{eq squares}
\vert \lambda_1 n_1^2 + \lambda_2 n_2^2 + \lambda_3 n_3^2 + \lambda_4 n_4^2 + \lambda_5 n_5^2 \vert \leqslant \varepsilon,
\end{equation} provided the coefficients $\lambda_i$ are non-zero, not all of the same sign, and not all in pairwise rational ratio.

\begin{equation}
\label{eq squares}
\vert \lambda_1 n_1^2 + \lambda_2 n_2^2 + \lambda_3 n_3^2 + \lambda_4 n_4^2 + \lambda_5 n_5^2 \vert \leqslant \varepsilon,
\end{equation}

A result first claimed in \cite{Ba67} by A. Baker\footnote{In fact Baker proved a slightly different result, writing in \cite{Ba67} that the result we quote here followed easily from the then-existing methods.} states that for any fixed positive $\varepsilon$ there exist infinitely many triples of primes $(p_1,p_2,p_3)$ satisfying 
\begin{equation}
\label{the type of inequality we're talking about}
\vert \lambda_1p_1 + \lambda_2p_2 + \lambda_3 p_3\vert \leqslant \varepsilon,
\end{equation}
\noindent assuming again that the coefficients $\lambda_i$ are non-zero, not all of the same sign, and not all in pairwise rational ratio.

\begin{equation}
\label{the type of inequality we're talking about}
\vert \lambda_1p_1 + \lambda_2p_2 + \lambda_3 p_3\vert \leqslant \varepsilon,
\end{equation}

\label{example three term irrational AP}
\emph{The first example could have been analysed by Davenport and Heilbronn using the methods of \cite{DaHe46}, but we include it here to demonstrate the simplest case in which Corollary \ref{much easier to state} applies. }

\emph{Let $$L := \Big(\begin{matrix} 1 & -\sqrt{2}  & -1 + \sqrt {2}\end{matrix}\Big).$$ Then $m=1$ and $d=3$, and manifestly there does not exist any non-zero row-vector in the row-space of $L$ that has two or fewer non-zero coordinates. Therefore Corollary \ref{much easier to state} applies, and so, if for each $N$ we have three functions $f_1,f_2,f_3:[N] \longrightarrow [-1,1]$ satisfying $\min_j \Vert f_j\Vert_{U^2[N]} \leqslant \rho$ for some $\rho$ in the range $0 < \rho \leqslant 1$, then we have
\begin{equation}
\label{three term Ap eq explicit}
\Big\vert\frac{1}{N^2}\sum\limits_{\substack{n_1,n_2,n_3\leqslant N\\ \vert n_1 - \sqrt{2}n_2 + (-1+\sqrt{2})n_3\vert\leqslant \varepsilon} }f_1(n_1)f_2(n_2)f_3(n_3)\Big\vert \ll_\varepsilon \rho^{\Omega(1)} +o_{\rho}(1)
\end{equation}}
\noindent \emph{as $N\rightarrow \infty$.} 

\emph{The statement (\ref{three term Ap eq explicit}) admits a different interpretation, which some readers may find more natural, that of counting the number of occurrences of a certain irrational pattern: a `three-term irrational arithmetic progression'. Indeed, recall that for $\theta \in \mathbb{R}$ we let $[\theta]$ denote $\lfloor \theta +\frac{1}{2}\rfloor$, i.e. the nearest integer to $\theta$. Then for any three functions $f_1,f_2,f_3:[N]\longrightarrow [-1,1]$, we make the definition
\begin{equation}
\label{reparametrised three term AP}
T(f_1,f_2,f_3):=\frac{1}{N^2}\sum\limits_{x,d\in \mathbb{Z}} f_3(x)f_2(x+d)f_1([x+\sqrt{2} d]).
\end{equation} Informally speaking, $T$ counts the number of near-occurrences of the pattern $(x,x+d,x+\sqrt{2}d)$, weighted by the functions $f_j$. By performing the change of variables $n_1 = [ x+\sqrt 2 d]$, $n_2 = x+d$, $n_3 = x$, and noting that $x+\sqrt{2}d\notin \frac{1}{2}\mathbb{Z}$, we see that}
\begin{equation}
\label{relating T}
T(f_1,f_2,f_3)=\frac{1}{N^2}\sum\limits_{\substack{n_1,n_2,n_3\leqslant N\\ \vert n_1 - \sqrt{2}n_2 + (-1+\sqrt{2})n_3\vert\leqslant \frac{1}{2}} }f_1(n_1)f_2(n_2)f_3(n_3).
\end{equation} \emph{By (\ref{three term Ap eq explicit}), this means that if $\min_j\Vert f_j\Vert_{U^2[N]}\leqslant \rho$ then
\begin{equation}
\label{bound on T}
\vert T(f_1,f_2,f_3)\vert \ll \rho^{\Omega(1)} + o_{\rho}(1)
\end{equation} as $N\rightarrow \infty$.} \\

\emph{Now suppose that $A_N$ is a subset of $[N]$ with $\vert A_N \vert = \alpha_N N$. Let }
\begin{equation*}
f_{A_N}:=1_{A_N} - \alpha_N 1_{[N]}
\end{equation*}
\noindent \emph{be its so-called `balanced function'. By the usual telescoping trick, $T(1_{A_N},1_{A_N},1_{A_N})$ is equal to
\begin{align*}
T(\alpha_N 1_{[N]},\alpha_N 1_{[N]},\alpha_N 1_{[N]})+ 
T(f_{A_N},\alpha_N 1_{[N]},\alpha_N 1_{[N]})+T(1_{A_N},f_{A_N},\alpha_N 1_{[N]})\nonumber \\ +T(1_{A_N},1_{A_N},f_{A_N}).
\end{align*}
\noindent One may then bound the final three terms using $\Vert f_{A_N}\Vert_{U^2[N]}$ and, from the relation (\ref{relating T}), one has then established that, provided $\Vert f_{A_N}\Vert_{U^2[N]}\leqslant \rho$,
\begin{equation*}
\frac{1}{N^2}\sum\limits_{x,d\in \mathbb{Z}} 1_{A_N}(x)1_{A_N}(x+d)1_{A_N}([ x+\sqrt{2} d])
\end{equation*}
\noindent is equal to
\begin{equation}
\label{counting three term APS} \frac{\alpha_N^3}{N^2}\sum\limits_{x,d\in \mathbb{Z}} 1_{[N]}(x)1_{[N]}(x+d)1_{[N]}([ x+\sqrt{2} d]) +O(\rho^{\Omega(1)}) + o_{\rho}(1)
\end{equation}
as $N\rightarrow \infty$. If $\Vert f_{A_N}\Vert_{U^2[N]} = o(1)$ as $N\rightarrow \infty$ then, by picking $\rho = \rho(N)$ to be a quantity that tends to zero suitably slowly, one can ensure that the error term in (\ref{counting three term APS}) is $o(1)$ as $N\rightarrow \infty$.}

\emph{As is familiar from \cite{Go01}, for bounded functions the $U^2$-norm is closely related to the Fourier transform. Indeed, we say that the family of sets $A_N$ is Fourier-uniform if the balanced functions $f_{A_N}$ satisfy \[ \sup\limits_{\theta\in[0,1]}\Big\vert \frac{1}{N}\sum\limits_{n\leqslant N} f_{A_N}(n) e(n\theta)\Big\vert = o(1)\] as $N\rightarrow \infty$, and it is a standard result (see \cite[Exercise 1.3.18]{Ta12}) that $A_N$ is Fourier uniform if and only if $\Vert f_{A_N}\Vert_{U^2[N]} = o(1)$ as $N\rightarrow \infty$. Therefore expression (\ref{counting three term APS}), and the remarks following it, imply the following corollary.}
\begin{Corollary}[Fourier-uniform sets]
\label{Corollary for Fourier uniform sets}
Let $\beta \in \mathbb{R} \setminus \mathbb{Q}$, and for each natural number $N$ let $A_N$ be a subset of $[N]$ with $\vert A_N\vert = \alpha_N N$. Suppose that $A_N$ is a Fourier-uniform family of sets.  Then \[\frac{1}{N^2}\sum\limits_{x,d\in \mathbb{Z}} 1_{A_N}(x)1_{A_N}(x+d)1_{A_N}([ x+\beta d])\] is equal to \[\frac{\alpha_N^3}{N^2}\sum\limits_{x,d\in \mathbb{Z}} 1_{[N]}(x)1_{[N]}(x+d)1_{[N]}([ x+\beta d])+o_\beta(1)\] as $N\rightarrow \infty$, where the $o_{\beta}(1)$ term also depends on the $o(1)$ term in the Fourier-uniformity expression for the family $A_N$. 
\end{Corollary}

\begin{equation}
\label{three term Ap eq explicit}
\Big\vert\frac{1}{N^2}\sum\limits_{\substack{n_1,n_2,n_3\leqslant N\\ \vert n_1 - \sqrt{2}n_2 + (-1+\sqrt{2})n_3\vert\leqslant \varepsilon} }f_1(n_1)f_2(n_2)f_3(n_3)\Big\vert \ll_\varepsilon \rho^{\Omega(1)} +o_{\rho}(1)
\end{equation}

\begin{equation}
\label{counting three term APS} \frac{\alpha_N^3}{N^2}\sum\limits_{x,d\in \mathbb{Z}} 1_{[N]}(x)1_{[N]}(x+d)1_{[N]}([ x+\sqrt{2} d]) +O(\rho^{\Omega(1)}) + o_{\rho}(1)
\end{equation}

\label{four term irrational AP}
\emph{Let 
\begin{equation}
\label{the equation giving an example of L}
L := \left(\begin{matrix}
1 & 0 & -\sqrt{2} & -1 + \sqrt{2} \\
0 & 1 & -\sqrt{3} & -1 + \sqrt{3}
\end{matrix} \right).
\end{equation} Since $\sqrt{2}$ and $\sqrt{3}$ are distinct irrationals it is not hard to see that all elements of the row-space of $L$ must have three or four non-zero coordinates, and so Corollary \ref{much easier to state} applies. Letting $f_1,f_2,f_3,f_4:[N] \longrightarrow [-1,1]$ be arbitrary functions, the reparametrisation $n_1 = [x + \sqrt{2} d]$, $n_2 = [x + \sqrt{3} d]$, $n_3 = x + d$, $n_4 = x$, shows that} \[\frac{1}{N^2}\sum\limits_{\substack{\mathbf{n} \in [N]^4 \\ \Vert L \mathbf{n} \Vert_\infty \leqslant \frac{1}{2}}} \Big( \prod\limits_{j=1}^4 f_j(n_j) \Big) = \frac{1}{N^2}\sum\limits_{x,d\in \mathbb{Z}} f_4(x) f_3(x+d) f_1([x+\sqrt{2}d]) f_2([ x+\sqrt{3}d]).\]
\emph{Corollary \ref{much easier to state} controls the left-hand side of this expression in terms of the Gowers norms of the functions $f_j$, and so the right-hand side is controlled as well.}

\begin{equation}
\label{the equation giving an example of L}
L := \left(\begin{matrix}
1 & 0 & -\sqrt{2} & -1 + \sqrt{2} \\
0 & 1 & -\sqrt{3} & -1 + \sqrt{3}
\end{matrix} \right).
\end{equation}

\label{Corollary irrational szem}
Let $\theta_1,\dots,\theta _s \in \mathbb{R}$ be distinct irrational numbers. For each natural number $N$ let $A_N$ be a subset of $[N]$, with $\vert A_N\vert = \alpha_N N$ and with balanced function $f_{A_N}$. Suppose that $\Vert f_{A_N}\Vert_{U^{s+1}[N]} = o(1)$ as $N\rightarrow \infty$. Then 
\begin{equation}
\label{particular patterns}
\frac{1}{N^2} \sum\limits_{x,d \in \mathbb{Z}} 1_{A_N}(x) 1_{A_N}(x+d)\Big (\prod\limits_{i=1}^s 1_{A_N}([x + \theta_i d]) \Big )\end{equation}\noindent is equal to
\begin{equation*}
\frac{\alpha_N^{s+2}}{N^2} \sum\limits_{x,d \in \mathbb{Z}} 1_{[N]}(x) 1_{[N]}(x+d)\Big (\prod\limits_{i=1}^s 1_{[N]}([x + \theta_i d]) \Big ) + o(1)
\end{equation*}
\noindent as $N\rightarrow \infty$, where the $o(1)$ error term may depend on $\theta_1,\dots,\theta_s$ and on the rate of decay of $\Vert f_{A_N}\Vert_{U^{s+1}[N]}$.

Apply Corollary \ref{much easier to state} to the $s$-by-$s+2$ matrix 
\begin{equation}
\label{general irrational L}
L = \left( \begin{matrix} I & -\boldsymbol{\theta} & -1 + \boldsymbol{\theta} \end{matrix} \right),
\end{equation} where $I$ denotes the identity matrix and $\boldsymbol{\theta}$ denotes the vector $(\theta_1,\dots,\theta_s)^T \in \mathbb{R}^{s}$.

\begin{equation}
\label{mobius example}\sum\limits_{\substack{\mathbf{n}\in [N]^4\\ n_1 - n_2 = n_2 - n_3\\ \vert (n_2 -n_3) - \sqrt {2}(n_3 - n_4)\vert \leqslant \frac{1}{2}}} \mu(n_1)\mu(n_2)\mu(n_3)\mu(n_4)  = o(N^2)
\end{equation}

\label{Definition solution count}
Let $N,m,d$ be natural numbers, and let $L:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ be a linear map. Let $F:\mathbb{R}^d\longrightarrow [0,1]$ and $G:\mathbb{R}^m\longrightarrow [0,1]$ be two functions, with $F$ supported on $[-N,N]^d$ and $G$ compactly supported. Let $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ be arbitrary functions. We define 
\begin{equation}
\label{original inequality}
T_{F,G,N}^L(f_1,\dots,f_d) :=  \frac{1}{N^{d-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^d}\Big(\prod\limits_{j=1}^d f_j(n_j)\Big)F(\mathbf{n})G(L\mathbf{n}).
\end{equation}

\label{Example approx function}
\emph{Suppose that, as a matrix, 
\begin{equation*}
L := \left(\begin{matrix} 1 & -\sqrt{2}  & -1 + \sqrt {2}\end{matrix}\right)
\end{equation*} as in Example \ref{example three term irrational AP}. Then $L$ is purely irrational, i.e. $u=0$, since its coefficients are not all in rational ratio. Therefore $A_L(\tau_1,\tau_2)$ is equal to \[ \inf\limits_{\substack{k\in \mathbb{R}: \tau_1 \leqslant \vert k\vert \leqslant \tau_2^{-1} }} \max(\Vert k\Vert_{\mathbb{R}/\mathbb{Z}},\Vert -k \sqrt{2}\Vert_{\mathbb{R}/\mathbb{Z}}, \Vert -k+k\sqrt{2}\Vert_{\mathbb{R}/\mathbb{Z}}). \] As we said above, we seek an upper bound on $A_L(\tau_1,\tau_2)^{-1}$. To this end, we claim that, for this particular $L$ and for all $\tau_1,\tau_2 \in (0,1]$, one has \[ A_L(\tau_1,\tau_2) \gg \min (\tau_1,\tau_2).\]}
\emph{Indeed, we know that, for all $q \in \mathbb{N}$, $\Vert q \sqrt{2} \Vert_{\mathbb{R}/\mathbb{Z}} \geqslant 1/(10q)$. This is the statement that $\sqrt{2}$ is a badly approximable irrational. The proof is straightforward: if there were some natural number $p$ for which $\vert q\sqrt{2} - p\vert < 1/(10q)$, then \[ 1 \leqslant \vert 2q^{2} - p^2\vert < \frac{\sqrt{2}}{10} + \frac{p}{10q} < \frac{\sqrt{2}}{5} + \frac{1}{10},\] which is a contradiction.}

\emph{Suppose first that $\Vert k\Vert_{\mathbb{R}/\mathbb{Z}}\leqslant \tau_2/100$                                                                                  and $1/2 \leqslant \vert k\vert \leqslant \tau_2^{-1}$. Then, replacing $k$ by $[k]$ (the nearest integer to $k$), we can conclude that}
\begin{align*}
\max(\Vert -k \sqrt{2}\Vert_{\mathbb{R}/\mathbb{Z}}, \Vert -k+k\sqrt{2}\Vert_{\mathbb{R}/\mathbb{Z}}) &\geqslant \Vert [k] \sqrt{2}\Vert_{\mathbb{R}/\mathbb{Z}} - \frac{\tau_2}{50} \\
& \geqslant \frac{1}{10 [k]} - \frac{\tau_2}{50}  \\
& \geqslant\frac{1}{10\tau_2^{-1} + 10} - \frac{\tau_2}{50}  \\
&\gg \tau_2.
\end{align*}

\emph{Otherwise, one has \[ \Vert k\Vert_{\mathbb{R}/\mathbb{Z}} \gg \min(\tau_1,\tau_2).\] Therefore, \[A_L(\tau_1,\tau_2) \gg \min(\tau_1, \tau_2)\] as claimed.}

\begin{equation}
\label{approximation function in the algebraic case}
A_L(\tau_1,\tau_2) \gg_L \min(\tau_1,\tau_2^{O_L(1)}),
\end{equation}

\label{Definition rank variety}
Let $m,d$ be natural numbers satisfying $d\geqslant m+1$. Let $V_{\operatorname{rank}}(m,d)$ denote the set of all linear maps $L:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ whose rank is less than $m$. We call $V_{\operatorname{rank}}(m,d)$ the \emph{low-rank variety}.

 Let $V_{ \operatorname{rank}}^{\operatorname{unif}}(m,d)$ denote the set of all linear maps $L:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ for which there exists a standard basis vector of $\mathbb{R}^d$, say $\mathbf{e_i}$, for which $L|_{\operatorname{span}(\mathbf{e_j}:j\neq i)}$ has rank less than $m$. We call $V_{ \operatorname{rank}}^{\operatorname{unif}}(m,d)$ the \emph{uniform low-rank variety}.

\begin{equation}
\label{conditions for equations}
L \notin V_{\operatorname{rank}}(m,d) \qquad \text{or} \qquad L \notin V_{\operatorname{degen}}^*(m,d).
\end{equation}

\label{Example bad behaviour}
\emph{It may be instructive to consider a matrix such as $$L = \left(\begin{matrix}
1 +N^{-1}& \sqrt{3}+N^{-\frac{1}{2}} & \pi & -\pi+\sqrt{2} \\
2 & 2\sqrt{3}+N^{-\frac{1}{2}} & -\sqrt{5} & e
\end{matrix} \right).$$ We observe that $L$ has rank 2 and $L\notin V_{\operatorname{degen}}^*(2,4)$. If one knew Theorem \ref{Linear equations in bounded functions non quantitative} and the conditions (\ref{conditions for equations}), then one might perhaps have hoped to apply the theory of Gowers norms to bound the number of solutions to inequalities given by $L$. However, by considering perturbations of the first two columns, we see that $\operatorname{dist}(L,V_{\operatorname{degen}}^*(2,4))=o(1)$ as $N\rightarrow \infty$. Indeed, one may perturb $L$ by $O(N^{-1/2})$ such that there is a vector $(0,0,x_3,x_4)$ in the row space. So, despite the fact that $L$ is non-degenerate from the point of view of equations, $L$ \emph{is} degenerate from the point of view of inequalities and the conditions (\ref{conditions for inequalities}). Thus, our main theorem on inequalities will not apply to this $L$. }

\emph{Furthermore, we have another result (Theorem \ref{Converse to main theorem} below) which shows that one cannot possibly use Gowers norms to control inequalities given by such an $L$. Therefore, whatever methods we use to prove Theorem \ref{Main Theorem chapter 3}, these methods must necessarily break down when applied to this example.}\\

\label{Main Theorem chapter 3}
Let $m,d$ be natural numbers, satisfying $d\geqslant m+2$, and let $\varepsilon , c,  C, C^\prime$ be positive reals. Let $N$ be an integer parameter and let $L = L(N):\mathbb{R}^d \longrightarrow \mathbb{R}^m$ be a surjective linear map that satisfies $\Vert L\Vert_\infty\leqslant C$. Let $A_L:(0,1]\times (0,1]\longrightarrow (0,\infty)$ be the approximation function of $L$. Suppose further that $\operatorname{dist}(L,V_{\operatorname{rank}}^{\operatorname{unif}}(m,d)) \geqslant c$, that $\operatorname{dist}(L,V^*_{\operatorname{degen}}(m,d))\geqslant c^\prime$, and that $L$ has rational complexity at most $C^\prime$. Then there exists a natural number $s$ at most $d-2$, independent of $\varepsilon$, such that the following is true. Let $F:\mathbb{R}^d\longrightarrow [0,1]$ be the indicator function of $[1,N]^d$, and let $G:\mathbb{R}^m\longrightarrow [0,1]$ be the indicator function of a convex domain contained in $[-\varepsilon, \varepsilon]^m$. Let $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ be arbitrary functions, and suppose that \[ \min_j \Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho,\] for some parameter $\rho$ in the range $0<\rho \leqslant 1$. Then 
\begin{equation}
\label{main equation chapter 3 theorem}
T^{L}_{F,G,N}(f_1,\dots,f_{d})\ll_{c,c^\prime,C,C^\prime,\varepsilon} \rho^{\Omega(1)} + o_{\rho,A_L,c,c^\prime,C,C^\prime}(1)
\end{equation} as $N\rightarrow \infty$.  The $o_{\rho,A_L,c,c^\prime,C,C^\prime}(1)$ term may be bounded above by \[ N^{-\Omega(1)}\rho^{-O(1)} A_L(\Omega_{c,c^\prime,C,C^{\prime}}(1),\rho)^{-1}.\]

\label{Converse to main theorem}
Let $m,d$ be natural numbers, satisfying $d\geqslant m+2$, and let $\varepsilon, c, C$ be positive constants. For each natural number $N$, let $L = L(N):\mathbb{R}^{d}\longrightarrow \mathbb{R}^m$ be a linear map satisfying $\Vert L\Vert_\infty\leqslant C$. Let $F:\mathbb{R}^d\longrightarrow [0,1]$ denote the indicator function of $[1,N]^d$ and $G:\mathbb{R}^m\longrightarrow [0,1]$ denote the indicator function of $[-\varepsilon,\varepsilon]^m$. Assume further that $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d))\geqslant c$ and that $T_{F,G,N}^L(1,\dots,1)\gg_{c,C,\varepsilon} 1$ for large enough $N$.

Suppose that $$\liminf\limits_{N\rightarrow\infty}\operatorname{dist}(L,V^*_{\operatorname{degen}}(m,d)) = 0.$$ Let $s$ be a natural number, let $H:\mathbb{R}_{>0}\rightarrow \mathbb{R}_{>0}$ be any function satisfying $H(\rho) = \kappa(\rho)$, and for each $N$ let $E_{\rho}(N)$ denote some error term depending on a parameter $\rho$ and satisfying $E_{\rho}(N) = o_{\rho}(1)$ as $N \rightarrow \infty$. Then one can find infinitely many natural numbers $N$ such that there exist functions $f_1,\dots,f_d:[N]\rightarrow [-1,1]$ and some $\rho$ at most $1$ such that both \[ \min_j\Vert f_j\Vert_{U^{s+1}[N]}\leqslant\rho\] and 
\begin{equation}
\label{conclusion of converse theorem}
\vert T_{F,G,N}^L(f_1,\dots,f_d)\vert > H(\rho)+E_{\rho}(N).
\end{equation}

\begin{equation}
\label{cut range of summation}
 T_{F, \widetilde{G},N}^L(f_1,\dots,f_4) \approx \frac{1}{N^2} \sum\limits_{\substack{\mathbf{n} \in \mathbb{Z}^4 \\ \Vert L \mathbf{n}\Vert_\infty \leqslant 10 - \delta \\ (\begin{smallmatrix}5 & 1 \end{smallmatrix})L\mathbf{n} = 0}}\Big(\prod\limits_{j=1}^4 f_j(n_j)\Big) F(\mathbf{n}).
 \end{equation}

This enables us to decompose $T_{F,G,N}^L(f_1,\dots,f_4)$ into three separate expressions, each of the form 
\begin{equation}
\label{the expression that doesn't change}
\frac{1}{N^2} \sum\limits_{\mathbf{m} \in \mathbb{Z}^3 } \Big( \prod\limits_{j=1}^4 f_j(\Xi(\mathbf{m})_j+ \widetilde{\mathbf{r}}_j) \Big) F(\Xi(\mathbf{m}) + \widetilde{\mathbf{r}})1_{[-10,10]^2}(L(\Xi\mathbf{m} + \widetilde{\mathbf{r}}))
\end{equation} for some different vector $\widetilde{\mathbf{r}} \in \mathbb{Z}^4$, where $\Xi(\mathbf{m})_j$ denotes the $j^{th}$ coordinate of $\Xi(\mathbf{m})$.

\begin{equation}
\label{the expression that doesn't change}
\frac{1}{N^2} \sum\limits_{\mathbf{m} \in \mathbb{Z}^3 } \Big( \prod\limits_{j=1}^4 f_j(\Xi(\mathbf{m})_j+ \widetilde{\mathbf{r}}_j) \Big) F(\Xi(\mathbf{m}) + \widetilde{\mathbf{r}})1_{[-10,10]^2}(L(\Xi\mathbf{m} + \widetilde{\mathbf{r}}))
\end{equation}

For a function $f: [N] \longrightarrow [-1,1]$ and a small parameter $\eta$, let $\widetilde{f}: \mathbb{R} \longrightarrow [-1,1]$ denote the function \[ \widetilde{f}(x) = \begin{cases}
f(n) & \text{if } \vert n-x\vert \leqslant \eta \\
0 & \text{otherwise,} \end{cases} \] i.e. $\widetilde{f}$ is a `fattened' version of $f$.

\begin{align}
\label{Lipschitz is needed equation}
\widetilde{T}_{F,G,N}^L(\widetilde{f_1},\dots,\widetilde{f_d}) &= \frac{1}{N^{d-m}} \sum\limits_{ \mathbf{n} \in \mathbb{Z}^d} \Big(\prod\limits_{j=1}^d f_j(n_j)\Big) \int\limits_{\mathbf{y} \in \mathbb{R}^d} F(\mathbf{y}) G(L\mathbf{y}) 1_{[-\eta,\eta]^d}(\mathbf{y} - \mathbf{n}) \, d\mathbf{y} \nonumber \\ &\approx \frac{1}{N^{d-m}} \sum\limits_{ \mathbf{n} \in \mathbb{Z}^d} \Big(\prod\limits_{j=1}^d f_j(n_j)\Big) F(\mathbf{n}) G(L\mathbf{n}) \int\limits_{\mathbf{y} \in \mathbb{R}^d} 1_{[-\eta,\eta]^d}(\mathbf{y} - \mathbf{n}) \, d\mathbf{y} \nonumber \\
& \approx (2 \eta)^dT_{F,G,N}^L(f_1,\dots,f_d),
 \end{align}

\label{rank matrix}
Let $m,d$ be natural numbers, with $d\geqslant m+1$. Let $c,C$ be positive constants. Then there are positive constants $D_{c,C}, D^\prime_{c,C}$ for which the following holds. Let $L:\mathbb{R}^d\longrightarrow \mathbb{R}^m$ be a surjective linear map, denoted by matrix $(\lambda_{ij})_{i\leqslant m,j\leqslant d}$, and assume that $\Vert L\Vert_\infty \leqslant C$ and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$. Then there exists a matrix $M$ that is an $m$-by-$m$ submatrix of $L$ and enjoys the following properties:
\begin{enumerate}[(1)]
\item  $\vert\operatorname{det}M\vert \geqslant D_{c,C}$; \\
\item $\Vert M^{-1}\Vert_{\infty} \leqslant D^\prime_{c,C}$.\\
\end{enumerate}
\noindent We call such a matrix $M$ a \emph{rank matrix} of $L$. Furthermore,\\
\begin{enumerate}[(1)]
\setcounter{enumi}{2}
\item Let $\mathbf{v}\in \mathbb{R}^d$ be a vector such that $\mathbf{v}^T$ is in the row-space of $L$, and suppose that $\Vert \mathbf{v}\Vert_\infty \leqslant C_1$ for some positive constant $C_1$. Then for all $i$ in the range $1\leqslant i\leqslant m$ there exist coefficients $a_i$ satisfying $\vert a_i\vert = O_{c,C,C_1}(1)$ such that $\sum\limits_{i=1}^m a_i \lambda_{ij} = v_{j}$ for all $j$ in the range $1\leqslant j\leqslant d$. \\
\end{enumerate}
Finally,\\
\begin{enumerate}
\setcounter{enumi}{3}
\item If $L$ satisfies the stronger hypothesis $\operatorname{dist}(L,V_{\operatorname{rank}}^{\operatorname{unif}}(m,d))\geqslant c$, then, for each $j$, there exists a rank matrix of $L$ that doesn't include the $j^{th}$ column of $L$.
\end{enumerate}

\label{Lemma upper bound involving integral}
Let $N,m,d$ be natural numbers, with $d\geqslant m+1$. Let $c,C,\varepsilon$ be positive constants, and let $\sigma_G$ be a parameter in the range $0<\sigma_G < 1/2$. Suppose that $L:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ is a purely irrational surjective linear map, satisfying $\Vert L\Vert_\infty \leqslant C$ and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$. Let $A_L$ denote the approximation function of $L$. Let $F:\mathbb{R}^d \longrightarrow [0,1]$ be supported on $[-N,N]^d$, and let $G:\mathbb{R}^m\longrightarrow [0,1]$ be a Lipschitz function, with Lipschitz constant $O(1/\sigma_G)$, supported on $[-\varepsilon,\varepsilon]^m$. Assume further that $\int_{\mathbf{x}} G(\mathbf{x}) \, d\mathbf{x} = O_\varepsilon(\sigma_G)$. Then for all $\tau_2$ in the range $0<\tau_2\leqslant 1$, 
\begin{equation*}
 T_{F,G,N}^L(1,\dots,1) \ll_{c,C,\varepsilon} \sigma_G + \frac{\tau_2^{1/2}}{\sigma _G} +  \frac{\tau_2^{-O(1)}A_L(\Omega_{c,C}(1),\tau_2)^{-1}}{N}.
 \end{equation*}

Following the proof of Lemma \ref{Lemma crude bound on number of solutions} verbatim, we arrive at the bound 
\begin{equation}
\label{we arrive at the bound}
T_{F,G,N}^L(1,\dots,1) \ll_{c,C,\varepsilon} \frac{1}{N^{d-m}}\sum\limits_{\substack{n_{m+1},\dots,n_d \in \mathbb{Z} \\ \vert n_{m+1}\vert,\dots,\vert n_{d}\vert \leqslant N}} \widetilde{G}(\sum_{j=m+1}^d \mathbf{v_j} n_j),
\end{equation} where $\mathbf{v_j}$ denotes the $j^{th}$ column of the matrix $M^{-1}L$, and $\widetilde{G}:\mathbb{R}^m \longrightarrow [0,1]$ denotes the function \[ \widetilde{G}(\mathbf{x}) = \sum\limits_{\mathbf{a} \in \mathbb{Z}^m} (G\circ M)(\mathbf{a} + \mathbf{x}).\] It remains to estimate the right-hand side of (\ref{we arrive at the bound}). \\

We may consider $\widetilde{G}$ as a function on $\mathbb{R}^m/\mathbb{Z}^m$. With respect to the metric $\Vert \mathbf{x}\Vert_{\mathbb{R}^m/\mathbb{Z}^m}$, $\widetilde{G}$ is Lipschitz with Lipschitz constant $O_{c,C,\varepsilon}(1/\sigma_G)$. Also, \[\int\limits_{\mathbf{x}\in [0,1)^m} \widetilde{G}(\mathbf{x}) \, d\mathbf{x} = \int\limits_{\mathbf{x}\in \mathbb{R}^m} (G \circ M)(\mathbf{x}) \, d\mathbf{x} = O_{c,C,\varepsilon}(\sigma_G).\] By \cite[Lemma A.9]{GrTa08}, which we recall in Lemma \ref{Fourier transforms of Lipschitz functions on tori}, for any $X$ at least $2$ we may write
\begin{equation}
\label{equation discrete fourier approximation}
\widetilde{G}(\mathbf{x}) = \sum\limits_{ \substack{\mathbf{k} \in\mathbb{Z}^m \\ \Vert \mathbf{k} \Vert_\infty \leqslant X}} b_X(\mathbf{k}) e(\mathbf{k} \cdot \mathbf{x}) + O_{c,C,\varepsilon}\Big(\frac{ \log X}{\sigma_G X}\Big),
\end{equation}  where $b_X(\mathbf{k})\in\mathbb{C}$ and satisfies $\vert b_X(\mathbf{k}) \vert = O(1)$. Moreover\footnote{This final fact is not given explicitly in the statement of \cite[Lemma A.9]{GrTa08}, although it is given in the proof. In any case, it may be immediately deduced from (\ref{equation discrete fourier approximation}), by letting $X$ tend to infinity and integrating (\ref{equation discrete fourier approximation}) over all $\mathbf{x} \in \mathbb{R}^m/\mathbb{Z}^m$.} $b_X(\mathbf{0}) = \int_{\mathbf{x} \in [0,1)^m} \widetilde{G}(\mathbf{x}) \, d\mathbf{x}$. 

Returning to (\ref{we arrive at the bound}), we see that for any $X$ at least $2$ we may write 
\begin{equation}
\label{summing geomtric progression}
T_{F,G,N}^L(1,\dots,1) \ll_{c,C,\varepsilon} \sigma_G + \frac{\log X}{\sigma_G X} + X^{O(1)}\max\limits_{\substack{\mathbf{k} \in \mathbb{Z}^m \\ 0<\Vert \mathbf{k} \Vert_\infty \leqslant X}}\Big( \prod\limits_{j=m+1}^d \min (1,  N^{-1}\Vert \mathbf{k} \cdot \mathbf{v_j}\Vert^{-1}_{\mathbb{R}/\mathbb{Z}})\Big),
\end{equation} where the final error term comes from summing over the arithmetic progressions $[-N,N] \cap \mathbb{Z}$.

It remains to relate the final error term of (\ref{summing geomtric progression}) to the approximation function $A_L$. Since $L$ is purely irrational, 
\begin{align}
A_L(\tau_1,\tau_2) &=\inf\limits_{\substack{\varphi \in (\mathbb{R}^m)^*\\ \tau_1 \leqslant  \Vert \varphi \Vert_\infty \leqslant \tau_2^{-1}} } \operatorname{dist} (L^* \varphi, (\mathbb{Z}^d)^T )\nonumber.
\end{align}
\noindent Let $\tau_2$ be in the range $0 < \tau_2 \leqslant 1$. Then there exist positive parameters $D$ and $D^\prime$, depending only on $c$ and $C$, for which
\begin{align}
\label{purely irrational is really important here}
\min\limits_{\substack{ \mathbf{k} \in \mathbb{Z}^m \\ 0< \Vert \mathbf{k}\Vert_\infty \leqslant D\tau_2^{-1}}} \max( \{\Vert \mathbf{k}\cdot\mathbf{v_j}\Vert_{\mathbb{R}/\mathbb{Z}}: m+1\leqslant j\leqslant d\}) & = \min\limits_{\substack{ \mathbf{k} \in \mathbb{Z}^m \\ 0< \Vert \mathbf{k}\Vert_\infty \leqslant D\tau_2^{-1}}} \operatorname{dist}(\mathbf{k}^T M^{-1} L, (\mathbb{Z}^d)^T) \nonumber\\
& \geqslant \inf\limits_{\substack{ \mathbf{k} \in \mathbb{R}^m \\ 1\leqslant \Vert \mathbf{k}\Vert_\infty \leqslant D\tau_2^{-1}}} \operatorname{dist}(\mathbf{k}^T M^{-1} L, (\mathbb{Z}^d)^T) \nonumber \\
&\geqslant \inf\limits_{\substack{ \mathbf{k} \in \mathbb{R}^m \\ D^\prime \leqslant \Vert \mathbf{k}\Vert_\infty \leqslant \tau_2^{-1}}} \operatorname{dist}(\mathbf{k}^T L, (\mathbb{Z}^d)^T)\nonumber \\
& =  A_L(D^\prime, \tau_2).
\end{align}
\noindent Letting $X = D \tau_2^{-1}$, and substituting the bound (\ref{purely irrational is really important here}) into (\ref{summing geomtric progression}), one derives
