For a system of homogeneous linear forms $(\psi_1,\dots,\psi_m) = \Psi:\mathbb{R}^n\longrightarrow \mathbb{R}^m$, an extension $(\psi_1^\prime,\dots,\psi_m^\prime) = \Psi^\prime: \mathbb{R}^{n^\prime} \longrightarrow \mathbb{R}^m$ is a system of homogeneous linear forms on $\mathbb{R}^{n^\prime}$, for some $n^\prime$ with $n^\prime\geqslant n$, such that 
\begin{enumerate}[(1)]
\item $\Psi^\prime(\mathbb{R}^{n^\prime}) = \Psi(\mathbb{R}^n)$;
\item if we identify $\mathbb{R}^n$ with the subset $\mathbb{R}^{n}\times \{ 0\}^{n^\prime - n}$ in the obvious manner, then $\Psi$ is the restriction of $\Psi^\prime$ to this subset.
\end{enumerate}

\label{normal form algorithm}
Let $m,n$ be natural numbers, with $m\geqslant 3$, and let $c_1,C_1$ be positive constants. Let $(\psi_1,\dots,\psi_m) = \Psi:\mathbb{R}^n \longrightarrow \mathbb{R}^m$ be a system of homogeneous linear forms, and suppose that the coefficients of $\Psi$ are bounded above in absolute value by $C_1$. Furthermore, suppose that $\Psi$ has $c_1$-Cauchy-Schwarz complexity $s$, for some finite $s$. Then, for each $i \in [m]$, there is an extension $\Psi^\prime:\mathbb{R}^{n^\prime}\longrightarrow \mathbb{R}^m$ such that:
\begin{enumerate}[(1)]
\item $n^\prime = n+s+1 \leqslant n+m-1$; 
\item $\Psi^\prime$ is of the form $$\Psi^\prime(\mathbf{u}, w_1,\dots,w_{s+1}): = \Psi(\mathbf{u} + w_1\mathbf{f_1}+ \cdots + w_{s+1}\mathbf{f_{s+1}})$$ for some vectors $\mathbf{f_k}\in \mathbb{R}^n$, such that $\Vert \mathbf{f_k}\Vert_\infty=O_{c_1,C_1}(1)$ for every $k$;
\item $\Psi^\prime$ is in normal form with respect to $\psi_i^\prime$;
\item $\psi_i^\prime(\mathbf{0},\mathbf{w}) = w_1 + \cdots + w_{s+1}$.
\end{enumerate}

\label{Definition solution count rational separation}
Let $N,m,d,h$ be natural numbers, with $d\geqslant h\geqslant m+2$. Let $\varepsilon$ be positive. Let $\Xi = (\xi_1,\dots,\xi_d) :\mathbb{R}^h\longrightarrow \mathbb{R}^d$ and $L:\mathbb{R}^{h}\longrightarrow \mathbb{R}^m$ be linear maps. Let $F:\mathbb{R}^{h}\rightarrow [0,1]$ and $G:\mathbb{R}^m\rightarrow [0,1]$ be two functions, with $F$ supported on $[-N,N]^h$ and $G$ compactly supported. Let $\widetilde{\mathbf{r}} \in \mathbb{Z}^d$ be some vector, and let $f_1,\dots,f_{d}:\mathbb{R}\longrightarrow [-1,1]$ be arbitrary functions. We then define
\begin{equation}
\label{equation solution count rational separation}
T^{L,\Xi,\widetilde{\mathbf{r}}}_{F,G,N}(f_1,\dots,f_{d}) := \frac{1}{N^{h-m}}\sum\limits_{\mathbf{n} \in \mathbb{Z}^h}\Big(\prod\limits_{j=1}^{d}f_j(\xi_j(\mathbf{n})+ \widetilde{\mathbf{r}}_j)\Big)F(\mathbf{n})G(L\mathbf{n}).
\end{equation}

\label{Theorem rational set out version}
Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive constants. Let $\Xi = \Xi(N):\mathbb{R}^h\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and assume that $\Xi(\mathbb{Z}^{h}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$. Let $L = L(N):\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume that $\Vert \Xi \Vert_\infty \leqslant C$, $\Vert L \Vert_\infty \leqslant C$, $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$ and $\operatorname{dist}((\Xi,L),V_{\operatorname{degen},2}^*(m,d,h))\geqslant c$. Then there exists a natural number $s$ at most $d-2$, independent of $\varepsilon$, such that the following holds. Let $\sigma_F,\sigma_G$ be any two parameters in the range $0<\sigma_F,\sigma_G < 1/2$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$ with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a Lipschitz function supported on $[-\varepsilon,\varepsilon]^m$ with Lipschitz constant $O(1/\sigma_G)$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$. Suppose that $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ are arbitrary bounded functions satisfying  \[\min_j \Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho,\] for some $\rho$ in the range $0<\rho \leqslant 1$. Then
\begin{equation}
\label{expression rational separated}
 T^{L,\Xi,\widetilde{\mathbf{r}}}_{F,G,N}(f_1,\dots,f_{d})\ll_{c,C,\varepsilon}  \rho^{\Omega(1)} (\sigma_F^{-O(1)} + \sigma_G^{-O(1)}) + \sigma_F^{-O(1)}N^{-\Omega(1)}. 
\end{equation}

\label{Lemma dual space decomposition}
Let $u,d,$ be integers with $d\geqslant u+1$, and let $C,\eta$ be constants. Let $S:\mathbb{R}^d \longrightarrow \mathbb{R}^u$ be a surjective linear map with $S(\mathbb{Z}^d) \subseteq \mathbb{Z}^u$, and suppose that $\Vert S\Vert_\infty \leqslant C$. Let $\{\mathbf{a_1},\dots,\mathbf{a_u}\}$ be a basis for the lattice $S(\mathbb{Z}^d)$ that satisfies $\Vert \mathbf{a_i}\Vert_\infty = O_{C}(1)$ for every $i$. Let $\mathbf{x_1},\dots,\mathbf{x_u}\in\mathbb{Z}^d$ be vectors such that, for every $i$, $S(\mathbf{x_i}) = \mathbf{a_i}$ and $\Vert \mathbf{x_i}\Vert_\infty = O_{C}(1)$. Suppose that $\Xi:\mathbb{R}^{d-u}\longrightarrow \mathbb{R}^d$ is an injective linear map such that $\operatorname{im} \Xi = \ker S$ and such that $\Xi(\mathbb{Z}^{d-u}) = \mathbb{Z}^d \cap\operatorname{im} \Xi$. Suppose further that $\Vert \Xi\Vert_\infty \leqslant C$. 

Let $\mathbf{w_1},\dots,\mathbf{w_{d-u}}$ denote the standard basis vectors in $\mathbb{R}^{d-u}$. Then 
\begin{enumerate}[(1)]
\item the set $\mathcal{B}: = \{ \mathbf{x_i}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j}): j\leqslant d-u\}$ is a basis for $\mathbb{R}^d$, and a lattice basis for $\mathbb{Z}^d$;
\item writing $\mathcal{B}^* := \{ \mathbf{x_i^*}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j})^*: j\leqslant d-u\}$ for the dual basis, both the change of basis matrix between the standard dual basis and $\mathcal{B}^*$ and the inverse of this matrix have integer coordinates. The coefficients of both of these matrices are bounded in absolute value by $O_{C}(1)$.
\end{enumerate}

\noindent  Write $V: = \operatorname{span}(\mathbf{x_i^*}: i\leqslant u)$ and $W: = \operatorname{span}(\Xi(\mathbf{w_j})^*: j\leqslant d-u)$. Then

\begin{enumerate}[(1)]
\setcounter{enumi}{2}
\item $V = S^*((\mathbb{R}^u)^*)$;
\item Suppose that $\varphi \in (\mathbb{R}^d)^*$ satisfies $\Vert \Xi^*(\varphi)\Vert_\infty \leqslant \eta$. Then, writing $\varphi = \varphi_V + \varphi_W$ with $\varphi_V \in V$ and $\varphi_W \in W$, we have $\Vert \varphi_W\Vert_\infty = O_C(\eta)$. 
\end{enumerate}

\label{Lemma generating a purely irrational map}
Let $\sigma_F$ be a parameter in the range $0<\sigma_F < 1/2$. Assume the hypotheses of Theorem \ref{Main Theorem chapter 3}, with the exception that $F:\mathbb{R}^d \longrightarrow [0,1]$ now denotes a Lipschitz function supported on $[-2N,2N]^d$ and with Lipschitz constant $O(1/\sigma_FN)$. Let $u$ be the rational dimension of $L$, and assume that $u\leqslant m-1$. Then there exists a surjective linear map $L^\prime:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^{m-u}$, an injective linear map $\Xi:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^d$, a finite subset $\widetilde{R}\subset \mathbb{Z}^d$, and, for each $\widetilde{\mathbf{r}} \in \widetilde{R}$, functions $F_{\widetilde{\mathbf{r}}}:\mathbb{R}^{d-u} \longrightarrow \mathbb [0,1]$ and $G_{\widetilde{\mathbf{r}}}:\mathbb{R}^{m-u} \longrightarrow [0,1]$, that together satisfy the following properties:
\begin{enumerate}[(1)]
\item $\Xi$ has integer coefficients, $\Vert \Xi \Vert_\infty  = O_{c,C}(1)$, and $\Xi(\mathbb{Z}^{d-u}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$;
\item $\vert \widetilde{R}\vert = O_{c,C}(1)$, and $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C}(1)$ for all $\widetilde{\mathbf{r}} \in \widetilde{R}$;
\item $F_{\widetilde{\mathbf{r}}}$ is supported on $[-O_{c,C}(N),O_{c,C}(N)]^{d-u}$, with Lipschitz constant $O_{c,C}(1/\sigma_FN)$, and $G_{\widetilde{\mathbf{r}}}$ is the indicator function of a convex domain contained in \\$[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m-u}$;
\item $T_{F,G,N}^L(f_1,\dots,f_d) = \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d);$
\item $L^\prime$ is purely irrational;
\item $\Vert L^\prime\Vert_\infty = O_{c,C}(1)$ and $\operatorname{dist}(L^\prime, V_{\operatorname{rank}}(m-u,d-u)) = \Omega_{c,C}(1)$;
\item $\operatorname{dist}((\Xi,L^\prime),V_{\operatorname{degen},2}^*(m-u,d,d-u)) = \Omega_{c,C}(1)$;
\item for all $\tau_1,\tau_2 \in (0,1]$, $A_{L^\prime}(\tau_1,\tau_2) \gg_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2))$;
\item for all $\tau_1,\tau_2 \in (0,1]$, $A_{L^\prime}(\tau_1,\tau_2) \ll_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2))$.
\end{enumerate}

First we note that the lemma is obvious when $u=0$, since one may take $\Xi:\mathbb{R}^d \longrightarrow \mathbb{R}^d$ to be the identity map, $\widetilde{\mathbf{r}}$ to be $\mathbf{0}$, and $L^\prime$ to be $L$. So assume that $u > 1$.\\

We proceed with a general reduction, familiar from our proof of Proposition \ref{Proposition maximal rational dimension case of main theorem}, in which we may assume that the first $m$ columns of $L$ form the identity matrix.

Indeed, let $\Theta:\mathbb{R}^m\longrightarrow \mathbb{R}^u$ be a rational map for $L$ with $\Vert \Theta \Vert_\infty \leqslant C$. Now let $\widetilde{L} : = M^{-1} L$, where $M$ is a rank matrix of $L$ (Proposition \ref{rank matrix}), which, without loss of generality, consists of the first $m$ columns of $L$. Let $\widetilde{\Theta} : = \Theta M$ and let $\widetilde{G}: = G\circ M$. Then \[ T_{F,G,N}^L(f_1,\dots,f_d) = T_{F,\widetilde{G},N} ^{\widetilde{L}}(f_1,\dots,f_d),\] and, considering $\widetilde{\Theta}$, $\widetilde{L}$ has rational complexity $O_{c,C}(1)$. Furthermore, $\widetilde{G}$ is the indicator function of a convex domain contained in $[-O_{c,C}(\varepsilon), O_{c,C}(\varepsilon)]^m$. We also have $\operatorname{dist}(\widetilde{L},V_{\operatorname{degen}}^*(m,d)) = \Omega_{c,C}(1)$. Finally, for all $\tau_1,\tau_2 \in (0,1]$, we have that\\ $A_{\widetilde{L}}(\tau_1,\tau_2) \asymp_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2))$. 

Therefore, by replacing $L$ with $\widetilde{L}$ and $G$ with $\widetilde{G}$, we may assume throughout the proof of Lemma \ref{Lemma generating a purely irrational map} that the first $m$ columns of $L$ form the identity matrix. This is at the cost of replacing $\varepsilon$ by $O_{c,C}(\varepsilon)$, $C$ by $O_{c,C}(1)$, and $c$ by $\Omega_{c,C}(1)$.  \\

Now let $\Theta:\mathbb{R}^m\longrightarrow \mathbb{R}^u$ be a rational map for $L$ with $\Vert \Theta \Vert_\infty = O_{c,C}(1)$. Since the first $m$ columns of $L$ form the identity matrix, $\Theta$ must have integer coefficients. \\

\textbf{Part (1)}: By rank-nullity $\ker (\Theta L)$ is a $d-u$ dimensional subspace of $\mathbb{R}^d$. The matrix of $\Theta L$ has integer coefficients and $\Vert \Theta L \Vert_\infty = O_{c,C}(1)$. Combining these two facts, we see that $\ker (\Theta L) \cap \mathbb{Z}^d$ is a $d-u$ dimensional lattice, and by the standard algorithms one can find a lattice basis $\mathbf{v^{(1)}},\dots, \mathbf{v^{(d-u)}} \in \mathbb{Z}^d$ that satisfies $\Vert \mathbf{v^{(i)}}\Vert_\infty = O_{c,C}(1)$ for every $i$. Define $\Xi:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^{d}$ by \[ \Xi(\mathbf{w}):= \sum\limits_{i=1}^{d-u} w_i \mathbf{v^{(i)}}.\] Then $\Xi$ satisfies property (1) of the lemma. Note that image of the map $L\Xi:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^m$ is exactly $\ker \Theta$. \\


\textbf{Part (2)}: Since $\Vert \Theta \Vert_\infty = O_{c,C}(1)$, if $\mathbf{y} \in\mathbb{R}^m$ and $\Theta(\mathbf{y}) = \mathbf{r}$ then  $ \Vert \mathbf{y} \Vert_\infty \gg_{c,C} \Vert\mathbf{r} \Vert_\infty$. Recall that the support of $G$ is contained within $[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^m$, and that $\Theta L(\mathbb{Z}^d) \subseteq \mathbb{Z}^u$. It follows that there are at most $O_{c,C,\varepsilon}(1)$ possible vectors $\mathbf{r} \in \mathbb{Z}^u$ for which there exists a vector $\mathbf{n} \in\mathbb{Z}^d$ for which both $G(L\mathbf{n}) \neq 0$ and $\Theta L \mathbf{n} = \mathbf{r}$. Let $R$ denote the set of all such vectors $\mathbf{r}$. 

For each $\mathbf{r} \in R$, there exists a vector $\widetilde{\mathbf{r}}\in \mathbb{Z}^d$ such that $\Theta L \widetilde{\mathbf{r}} = \mathbf{r}$ and $\Vert \widetilde{\mathbf{r}} \Vert_\infty = O_{c,C,\varepsilon}(1)$. Let $\widetilde{R}$ denote the set of these $\widetilde{\mathbf{r}}$. Then $\widetilde{R}$ satisfies part (2).\\

Before proceeding to prove part (3) of the lemma, we pause to apply Lemmas \ref{Lemma parametrising the image lattice} and \ref{Lemma dual space decomposition}. Indeed, applying these lemmas to the map $S: = \Theta L$, there exists a set $\{ \mathbf{a_1},\dots,\mathbf{a_u}\} \subset \mathbb{Z}^u$ that is a basis for the lattice $\Theta L(\mathbb{Z}^d)$ and for which $\Vert \mathbf{a_i}\Vert_\infty = O_{c,C}(1)$ for each $i$. Also, there exists a set of vectors $\{ \mathbf{x_1},\dots,\mathbf{x_u}\} \subset \mathbb{Z}^d$ such that $\Theta L(\mathbf{x_i})= \mathbf{a_i}$ for each $i$, and $\Vert \mathbf{x_i}\Vert_\infty = O_{c,C}(1)$. By Lemma \ref{Lemma dual space decomposition}, 
\begin{equation}
\label{basis for Rd}
 \mathcal{B}: = \{\mathbf{x_i}:i\leqslant u\} \cup \{ \Xi(\mathbf{w_j}):j\leqslant d-u\}
 \end{equation} is a basis for $\mathbb{R}^d$ and a lattice basis for $\mathbb{Z}^d$, where $\mathbf{w_1},\dots,\mathbf{w_{d-u}}$ denotes the standard basis of $\mathbb{R}^{d-u}$.\\ 




\textbf{Part (3)}: By the definition of $\widetilde{R}$, and the fact that $\Xi(\mathbb{Z}^{d-u}) = \mathbb{Z}^d \cap \ker (\Theta L)$, we have  
\begin{equation}
\label{equation getting integer rows}
T_{F,G,N}^L(f_1,\dots,f_d) = \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\frac{1}{N^{d-m}} \sum\limits_{\mathbf{n} \in \mathbb{Z}^{d-u}} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j) \Big)F(\Xi(\mathbf{n}) + \widetilde{\mathbf{r}}) G(L\Xi(\mathbf{n}) + L\widetilde{\mathbf{r}}),
\end{equation}
\noindent where $\widetilde{\mathbf{r}}_j$ denotes the $j^{\text{th}}$ coordinates of $\widetilde{\mathbf{r}}$. Now by an easy linear algebraic argument (recorded in Lemma \ref{Lemma construction of P}), 
\begin{equation}
\label{direct sum}
\mathbb{R}^m = \operatorname{span}(L\mathbf{x_i}:i\leqslant u) \oplus \ker \Theta
\end{equation} as an algebraic direct sum, and there exists an invertible linear map $P:\mathbb{R}^m \longrightarrow \mathbb{R}^m$ such that \begin{align}
\label{equation properties of P}
P((\operatorname{span}(L\mathbf{x_i}:i\leqslant u))) &= \mathbb{R}^u \times \{0\}^{m-u}, \\
\label{equation properties of P 2}
P(\ker \Theta) &= \{0\}^{u} \times \mathbb{R}^{m-u}, 
\end{align}
\noindent and both $\Vert P\Vert_\infty = O_{c,C}(1)$ and $\Vert P^{-1} \Vert_\infty = O_{c,C}(1)$. 

We have \[ G(L\Xi(\mathbf{n}) + L\widetilde{\mathbf{r}}) = (G \circ P^{-1})(PL\Xi(\mathbf{n}) + PL\widetilde{\mathbf{r}}),\] and we note that $PL\Xi(\mathbf{n}) \in \{0\}^u \times \mathbb{R}^{m-u}$ for every $\mathbf{n} \in \mathbb{Z}^{d-u}$. Define $G_{\widetilde{\mathbf{r}}}:\mathbb{R}^{m-u} \longrightarrow [0,1]$ by \[G_{\widetilde{\mathbf{r}}}(\mathbf{x}) : = (G\circ P^{-1})(\mathbf{x_0} + PL\widetilde{\mathbf{r}}),\] where $\mathbf{x_0}$ is the extension of $\mathbf{x}$ by $0$ in the first $u$ coordinates. Then the function $G_{\widetilde{\mathbf{r}}}$ is the indicator function of a convex set contained in $[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m-u}$. 

Define \[F_{\widetilde{\mathbf{r}}}(\mathbf{n}) : =  F(\Xi(\mathbf{n}) + \widetilde{\mathbf{r}}).\] Then $F_{\widetilde{\mathbf{r}}}$ has Lipschitz constant $O_{c,C}(1/\sigma_F N)$ and $F_{\widetilde{\mathbf{r}}}$ is supported on \\$[-O_{c,C,\varepsilon}(N),O_{c,C,\varepsilon}(N)]^{d-u}$. (For a full proof of this fact, apply Lemma \ref{Lemma bounded inverse} to the map $\Xi$). So $F_{\widetilde{\mathbf{r}}}$  and $G_{\widetilde{\mathbf{r}}}$ satisfy part (3).\\

\textbf{Part (4)}: Writing $\pi_{m-u}:\mathbb{R}^{m}\longrightarrow \mathbb{R}^{m-u}$ for the projection onto the final $m-u$ coordinates, expression (\ref{equation getting integer rows}) is equal to 
\begin{equation}
\label{equation end of second part}
\sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\frac{1}{N^{d-m}} \sum\limits_{\mathbf{n} \in \mathbb{Z}^{d-u}} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j) \Big)F_{\widetilde{\mathbf{r}}}(\mathbf{n})G_{\widetilde{\mathbf{r}}}( \pi_{m-u} PL\Xi(\mathbf{n})).
\end{equation} 
\noindent Let 
\begin{equation}
\label{equation definition of L prime}
L^\prime: = \pi_{m-u} PL\Xi.
\end{equation} Then $L^\prime:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^{m-u}$ is surjective, and \[T_{F,G,N}^L(f_1,\dots,f_d) = \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d).\] This resolves part (4).\\

\textbf{Part (5)}:  We wish to show that $L^\prime$ is purely irrational. Suppose for contradiction that there exists some surjective linear map $\varphi:\mathbb{R}^{m-u} \longrightarrow \mathbb{R}$ with $\varphi L^\prime (\mathbb{Z}^{d-u}) \subseteq \mathbb{Z}$, i.e. with $\varphi \pi_{m-u} PL\Xi(\mathbb{Z}^{d-u}) \subseteq \mathbb{Z}$. Then define the map $\Theta^\prime:\mathbb{R}^m \longrightarrow \mathbb{R}^{u+1}$ by \[ \Theta^\prime(\mathbf{x}) : = (\Theta(\mathbf{x}),\varphi \pi_{m-u} P(\mathbf{x})).\] Then $\Theta^\prime$ is surjective, and $\Theta^\prime L(\mathbb{Z}^d)\subseteq \mathbb{Z}^{u+1}$. (This second fact is immediately seen by writing $\mathbb{Z}^d$ with respect to the lattice basis $\mathcal{B}$ from (\ref{basis for Rd})). This contradicts the assumption that $L$ has rational dimension $u$. So $L^\prime$ is purely irrational.  \\

\textbf{Part (6)}: The bound $\Vert L^\prime\Vert_\infty = O_{c,C}(1)$ follows immediately from the bounds on the coefficients of $\Xi$, $L$, $P$, and $\pi_{m-u}$ separately. 

We wish to prove that $\operatorname{dist}(L^\prime, V_{\operatorname{rank}}(m-u,d-u)) \gg_{c,C} 1$, i.e. that\\ $\operatorname{dist}(\pi_{m-u} PL\Xi, V_{\operatorname{rank}}(m-u,d-u)) \gg_{c,C} 1$. Suppose for contradiction that, for a small parameter $\eta$, there exists a linear map $Q: \mathbb{R}^{d-u} \longrightarrow \mathbb{R}^{m-u}$ such that $\Vert Q\Vert_{\infty}<\eta$ and $\pi_{m-u} PL\Xi + Q$ has rank less than $m-u$. 
Recall that $PL\Xi (\mathbb{R}^{d-u}) = \{0\}^u \times \mathbb{R}^{m-u}$. So, extending $Q$ by zeros to a map $Q:\mathbb{R}^{d-u} \longrightarrow \{0\}^u \times \mathbb{R}^{m-u}$, and applying $P^{-1}$, there is a map $Q^\prime:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^m$ such that $\Vert Q^\prime\Vert_{\infty}=O_{c,C}(\eta)$ and $L\Xi + Q^\prime$ has rank less than $m-u$. 

We may factorise $Q^\prime = H\Xi$ for some $m$-by-$d$ matrix $H$. Indeed let \[\mathcal{B} := \{ \mathbf{x_i}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j}): j\leqslant d-u\}\] be the basis of $\mathbb{R}^d$ from (\ref{basis for Rd}), i.e. the basis formed by applying Lemma \ref{Lemma dual space decomposition} to the map $S: = \Theta L$. Define the linear map $H$ by $H(\Xi(\mathbf{w_j})): = Q^\prime(\mathbf{w_{j}})$ for each $j$ and $H(\mathbf{x_i}): = \mathbf{0}$ for each $i$. Since the change of basis matrix between $\mathcal{B}$ and the standard basis of $\mathbb{R}^d$ has integer coefficients with absolute values at most $O_{c,C}(1)$, it follows that the matrix representing $H$ with respect to the standard bases satisfies $\Vert H\Vert_\infty = O_{c,C}(\eta)$.

So we know that $(L+H)\Xi$ has rank less than $m-u$. But $\Xi:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^d$ is injective, so this implies that the rank of $L+H$ is less than $m$. Hence $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) = O_{c,C}(\eta)$, which contradicts the assumptions of the lemma (if $\eta$ is small enough). So $\operatorname{dist}(L^\prime,V_{\operatorname{rank}}(m-u,d-u)) \gg_{c,C} 1$ as required. \\

\textbf{Part (7)}: We wish to show that $\operatorname{dist}((\Xi,L^\prime),V_{\operatorname{degen},2}^*(m-u,d,d-u)) = \Omega_{c,C}(1)$. Suppose for contradiction that, for a small parameter $\eta$, there exists a linear map $Q:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^d$ such that  $\Vert Q\Vert_\infty \leqslant \eta$ and $\operatorname{dist}((\Xi + Q, L^\prime ),V_{\operatorname{degen},2}^*(m-u,d,d-u)) \leqslant \eta$. In other words, we suppose there exist two indices $i,j\leqslant d$, and a real number $\lambda$, such that $\mathbf{e_i}^* - \lambda\mathbf{e_j}^*$ is non-zero and \[ (\Xi + Q)^*(\mathbf{e_i}^* - \lambda\mathbf{e_j}^*) \in (L^\prime)^*((\mathbb{R}^{m-u})^*),\] where $\{\mathbf{e_1},\dots,\mathbf{e_d}\}$ denotes the standard basis of $\mathbb{R}^d$ and $\{\mathbf{e_1}^*,\dots,\mathbf{e_d}^*\}$ denotes the dual basis. Expanding out the definition of $L^\prime$, this means that there exists some $\varphi \in (\mathbb{R}^{m-u})^*$ such that \[\Xi^*(\mathbf{e_i}^* - \lambda\mathbf{e_j}^* - L^*(P^* \pi_{m-u}^*(\varphi))) = -Q^*(\mathbf{e_i}^* - \lambda\mathbf{e_j}^*).\] Because $\Vert Q\Vert_\infty \leqslant \eta$, this means that 
\begin{equation}
\label{about to be dualed}
\Vert \Xi^*(\mathbf{e_i}^* - \lambda\mathbf{e_j}^* - L^*(P^* \pi_{m-u}^*(\varphi)))\Vert_\infty = O(\eta).
\end{equation}

Let 
\begin{equation}
\label{funky dual basis}
\mathcal{B}^* := \{ \mathbf{x_i^*}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j})^*: j\leqslant d-u\}
\end{equation} denote the basis of $(\mathbb{R}^d)^*$ that is dual to the basis $\mathcal{B}$ from (\ref{basis for Rd}). It follows from part (4) of Lemma \ref{Lemma dual space decomposition} and (\ref{about to be dualed}) that \[\mathbf{e_i}^* - \lambda\mathbf{e_j}^* - L^*(P^* \pi_{m-u}^*(\varphi)) = \omega_V + \omega_W,\] where $\omega_V \in L^* \Theta^*((\mathbb{R}^u)^*)$, $\omega_W \in \operatorname{span}(\Xi(\mathbf{w_j})^*:j\leqslant d-u)$, and $\Vert\omega_W\Vert_\infty = O_{c,C}(\eta)$. So therefore \[ \mathbf{e_i}^* - \lambda\mathbf{e_j}^* = L^*(\alpha) + \omega_W,\] for some $\alpha \in (\mathbb{R}^m)^*$. 

This is enough to derive a contradiction. Indeed, without loss of generality one may assume that $\Vert \mathbf{e_i}^* - \lambda\mathbf{e_j}^*\Vert_\infty \geqslant 1$ (this is obvious if $i\neq j$, and if $i = j$ we may just pick $\lambda = 0$ at the outset). Therefore $\Vert \mathbf{e_i}^* - \lambda\mathbf{e_j}^* - \omega_W\Vert \geqslant 1/2$, provided $\eta$ is small enough. Since $\Vert L^*\Vert_\infty = O_{c,C}(1)$, we conclude that $\Vert \alpha\Vert_\infty = \Omega_{c,C}(1)$. 

This means that there exists a linear map $E:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ with $\Vert E \Vert_\infty = O_{c,C}(\eta)$ for which $E^*(\alpha) = \omega_W$. Then \[ \mathbf{e_i}^* - \lambda\mathbf{e_j}^* \in (L+E)^*((\mathbb{R}^{m})^*),\] and hence $\operatorname{dist}(L, V_{\operatorname{degen}}^*(m,d)) = O_{c,C}(\eta)$. This is a contradiction to the hypotheses of Theorem \ref{Main Theorem chapter 3}, provided $\eta$ is small enough, and hence $\operatorname{dist}((\Xi,L^\prime),V_{\operatorname{degen},2}^*(m-u,d,d-u)) = \Omega_{c,C}(1)$. \\

\textbf{Part (8)}: Let $\tau_1,\tau_2 \in (0,1]$. We desire to prove the relationship 
\begin{equation}
\label{claim of part 8}
A_{L^\prime}(\tau_1,\tau_2) \gg_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2)),
\end{equation}
\noindent where $L^\prime$ is as in (\ref{equation definition of L prime}).

We have already proved that $L^\prime$ is purely irrational (that was part (5) of the lemma). So, if $A_{L^\prime}(\tau_1,\tau_2)  <\eta$, for some $\eta$, there exists some $\varphi \in (\mathbb{R}^{m-u})^*$ for which $ \tau_1\leqslant \Vert \varphi\Vert_\infty \leqslant \tau_2^{-1}$ and for which \[\operatorname{dist}( (\pi_{m-u} PL\Xi)^*(\varphi),(\mathbb{Z}^{d-u})^T) <\eta,\] where, one recalls, we use $(\mathbb{Z}^{d-u})^T$ to denote the set of those functions in $(\mathbb{R}^{d-u})^*$ that have integer coordinates with respect to the standard dual basis. 

We claim that 
\begin{align}
\label{first approximation equation of part 8 of the lemma}
\operatorname{dist}(L^*(P^*\pi_{m-u}^*(\varphi)),(\mathbb{Z}^d)^T) \ll_{c,C}\eta;\\
\label{second approximation equation of part 8 of the lemma}
\Vert P^*\pi_{m-u}^*(\varphi)\Vert_\infty \ll_{c,C} \tau_2^{-1};\\
\label{third approximation equation of part 8 of the lemma}
\operatorname{dist}(P^*\pi_{m-u}^*(\varphi), \Theta^*((\mathbb{R}^{u})^*)) \gg_{c,C} \tau_1, 
\end{align}
\noindent from which (\ref{claim of part 8}) immediately follows. \\

Let us prove (\ref{first approximation equation of part 8 of the lemma}). Indeed, we already know that\\ $\operatorname{dist}( \Xi^* L^* P^* \pi_{m-u}^*(\varphi),(\mathbb{Z}^{d-u})^T) <\eta$, i.e. that 
\begin{equation}
\label{first approximation equation}
 \Vert \Xi^* L^* P^* \pi_{m-u}^*(\varphi) - \alpha\Vert_\infty <\eta,
 \end{equation} for some $\alpha \in (\mathbb{Z}^{d-u})^T$. Let us write $\alpha = \sum_{j=1}^{d-u} \lambda_j\mathbf{w_j}^*$ for some $\lambda_j \in \mathbb{Z}$, where $\mathbf{w_1},\dots,\mathbf{w_{d-u}}$ denotes the standard basis for $\mathbb{R}^{d-u}$ and $\mathbf{w_1}^*,\dots,\mathbf{w_{d-u}}^*$ denotes the dual basis. Let $\mathcal{B}^*$ be as in (\ref{funky dual basis}). Then $\mathbf{w_j}^* = \Xi^*((\Xi(\mathbf{w_j})^*)$, and so \[ \alpha = \Xi^*(\sum\limits_{j=1}^{d-u} \lambda_j \Xi(\mathbf{w_j}) ^*).\] So from (\ref{first approximation equation}) and the final part of Lemma \ref{Lemma dual space decomposition}, 
\begin{equation}
L^*P^* \pi_{m-u}^*(\varphi) - \sum\limits_{j=1}^{d-u} \lambda_j \Xi(\mathbf{w_j}) ^* = \omega_V + \omega_W,
\end{equation}
\noindent where $\omega_V \in \operatorname{span}(\mathbf{x_i^*}:i\leqslant u)$, $\omega_W \in \operatorname{span}(\Xi(\mathbf{w_j})^*:j\leqslant d-u)$, and $\Vert\omega_W\Vert_\infty = O_{c,C}(\eta)$. 

But $L^*P^* \pi_{m-u}^*(\varphi) \in \operatorname{span}(\Xi(\mathbf{w_j})^*:j\leqslant d-u)$ too. Indeed, for every $i$ at most $d-u$,
\[L^*P^* \pi_{m-u}^*(\varphi)(\mathbf{x_i}) = \varphi (\pi_{m-u} PL\mathbf{x_i}) = \varphi(\mathbf{0}) = 0,\] by the properties of $P$ (see (\ref{equation properties of P})). Therefore $\omega_V = \mathbf{0}$, and so \[\Vert L^*P^* \pi_{m-u}^*(\varphi) - \sum\limits_{j=1}^{d-u} \lambda_j \Xi(\mathbf{w_j}) ^*\Vert_\infty = O_{c,C}(\eta).\] Since  $\sum_{j=1}^{d-u} \lambda_j \Xi(\mathbf{w_j}) ^* \in (\mathbb{Z}^d)^T$, this implies (\ref{first approximation equation of part 8 of the lemma}) as claimed.\\


The bound (\ref{second approximation equation of part 8 of the lemma}) is immediate from the bounds on the coefficients of $P^*$ and $\pi_{m-u}^*$, so it remains to prove (\ref{third approximation equation of part 8 of the lemma}). Suppose for contradiction that, for some small parameter $\delta$, \[P^*\pi_{m-u}^*(\varphi) = \alpha_1 + \alpha_2,\] where $\alpha_1 \in \Theta^*((\mathbb{R}^{u})^*)$ and $\Vert \alpha_2 \Vert_\infty \leqslant \delta \tau_1$. We know that $\Vert \varphi \Vert_\infty \geqslant \tau_1$, which means that there is some standard basis vector $\mathbf{f_k} \in \mathbb{R}^{m-u}$ for which $\vert \varphi(\mathbf{f_k})\vert \geqslant \tau_1$. Let $\mathbf{b_{k+u}}$ be the standard basis vector of $\mathbb{R}^m$ for which $\pi_{m-u}(\mathbf{b_{k+u}}) = \mathbf{f_k}$. Recall the properties of $P$ (given in (\ref{equation properties of P}) and (\ref{equation properties of P 2})), in particular recall that $P:\ker \Theta \longrightarrow \{0\}^u \times \mathbb{R}^{m-u}$ is an isomorphism. Then \[\vert P^* \pi_{m-u}^*(\varphi)(P^{-1}(\mathbf{b_{k+u}}))\vert = \vert\pi_{m-u}^*(\varphi)(\mathbf{b_{k+u}})\vert = \vert \varphi(\mathbf{f_k})\vert \geqslant \tau_1.\] Note that $\Theta^*((\mathbb{R}^{u})^*) = (\ker \Theta)^{0}$, and so \[\vert P^* \pi_{m-u}^*(\varphi)(P^{-1}(\mathbf{b_{k+u}}))\vert = \vert(\alpha_1 + \alpha_2)(P^{-1}(\mathbf{b_{k+u}}))\vert = \vert \alpha_2(P^{-1}(\mathbf{b_{k+u}})) \vert \ll_{c,C} \delta \tau_1,\] as $P^{-1}(\mathbf{b_{k+u}}) \in \ker \Theta$ and satisfies $\Vert P^{-1}(\mathbf{b_{k+u}})\Vert_\infty = O_{c,C}(1)$. This is a contradiction if $\delta$ is small enough, and so (\ref{third approximation equation of part 8 of the lemma}) holds. This resolves part (8).\\

\textbf{Part (9)}: Let $\tau_1,\tau_2 \in (0,1]$. We desire to prove the relationship 
\begin{equation}
\label{claim of part 9}
A_{L^\prime}(\tau_1,\tau_2) \ll_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2)),
\end{equation}
\noindent where $L^\prime$ is as in (\ref{equation definition of L prime}).This inequality is the reverse inequality of part (8), and in fact it will not be required in the proof of any of our main theorems. However, it will be required in order to analyse $A_L(\tau_1,\tau_2)$ when $L$ has algebraic coefficients (in Appendix \ref{section algebraic approximation}), so we choose to state and prove it here, close to our argument for part (8).

Suppose that $A_L(\tau_1,\tau_2)<\eta$, for some parameter $\eta$. Then there exists some $\varphi\in (\mathbb{R}^m)^*$ such that $\operatorname{dist}(\varphi, \Theta^*((\mathbb{R}^u)^*)) \geqslant \tau_1$, $\Vert \varphi \Vert_\infty \leqslant \tau_2^{-1}$, and $\operatorname{dist}(L^*\varphi, (\mathbb{Z}^d)^T) < \eta$. So there exists some $\omega \in (\mathbb{Z}^d)^T$ for which \[ \Vert L^* \varphi - \omega\Vert_\infty < \eta.\] 

We expand both $L^*\varphi$ and $\omega$ with respect to the dual basis $\mathcal{B}^*$ from (\ref{funky dual basis}). So, 
\begin{align*}
L^*\varphi &= \sum\limits_{i=1}^u \lambda_i \mathbf{x_i^*} + \sum\limits_{j=1}^{d-u} \mu_j \Xi(\mathbf{w_j})^*\\
\omega& = \sum\limits_{i=1}^u \lambda_i^\prime \mathbf{x_i^*} + \sum\limits_{j=1}^{d-u} \mu_j^\prime \Xi(\mathbf{w_j})^*.
\end{align*}
\noindent Since $\mathcal{B}^*$ is a lattice basis for $(\mathbb{Z}^d)^T$, we have $\lambda_i^\prime \in \mathbb{Z}$ and $\mu_j^\prime \in\mathbb{Z}$ for each $i$ and $j$. Since the change of basis matrix between $\mathcal{B}^*$ and the standard dual basis has integer coefficients that are bounded in absolute value by $O_{c,C}(1)$ (part (2) of Lemma \ref{Lemma dual space decomposition}), one has $\vert \lambda_i - \lambda_i^\prime\vert = O_{c,C}(\eta)$ and $\vert \mu_j - \mu_j^\prime\vert = O_{c,C}(\eta)$ for each $i$ and $j$. 

Let $\mathbf{w_1^*}, \dots,\mathbf{w_{d-u}^*}$ denote the standard dual basis of $(\mathbb{R}^{d-u})^*$, and define \[\omega^\prime: = \sum\limits_{j=1}^{d-u} \mu_j^\prime \mathbf{w_j^*}.\] Certainly $\omega^\prime \in (\mathbb{Z}^{d-u})^T$. We claim that there exists a map $\varphi^\prime \in (\mathbb{R}^{m-u})^*$ such that $\tau_1 \ll_{c,C} \Vert \varphi^\prime \Vert_\infty \ll_{c,C} \tau_2^{-1}$ and $\Vert (L^\prime)^* \varphi^\prime - \omega^\prime\Vert_\infty \ll_{c,C} \eta$, which will immediately resolve (\ref{claim of part 9}) and part (9). \\

Indeed, recall the decomposition $\mathbb{R}^m =  (\operatorname{span}(L\mathbf{x_i}: i\leqslant u)) \oplus \ker \Theta$ as an algebraic direct sum from (\ref{direct sum}). Let $\varphi = \varphi_1 + \varphi_2$, where $\varphi_1 \in(\operatorname{span}(L\mathbf{x_i}: i\leqslant u))^{0} $ and $\varphi_2 \in (\ker \Theta)^{0}.$ Since $\operatorname{dist}(\varphi, (\ker \Theta)^{0}) \geqslant \tau_1$, we have $\Vert \varphi_1\Vert_\infty \geqslant \tau_1$. By the properties of the matrix $P$ ((\ref{equation properties of P}) and (\ref{equation properties of P 2})) there exists some $\varphi^\prime \in (\mathbb{R}^{m-u})^*$ such that \[\varphi_1 = P^* \pi_{m-u}^* \varphi^\prime.\] Furthermore, by evaluating $\varphi^\prime$ at the standard basis vectors, one sees that \[ \tau_1 \ll_{c,C} \Vert \varphi^\prime \Vert_\infty \ll_{c,C} \tau_2^{-1}.\] We shall use this $\varphi^\prime$.

By evaluating $L^*\varphi_1$ at the elements of $\mathcal{B}$ one immediately sees that  \[L^*\varphi_1 = \sum\limits_{j=1}^{d-u} \mu_j \Xi(\mathbf{w_j})^*.\] Hence \[\Xi^*L^*P^* \pi_{m-u}^* \varphi^\prime = \sum\limits_{j=1}^{d-u} \mu_j \mathbf{w_j^*},\] in other words $(L^\prime)^* \varphi^\prime = \sum_{j=1}^{d-u}\mu_j \mathbf{w_j^*}.$ But since $\vert \mu_j - \mu_j^\prime\vert = O_{c,C}(\eta)$ for each $j$, one has $\Vert (L^\prime)^* \varphi^\prime - \omega^\prime\Vert_\infty = O_{c,C} (\eta)$ as required. This settles part (9). \\

\noindent The entire lemma is settled.

\begin{equation}
\label{equation getting integer rows}
T_{F,G,N}^L(f_1,\dots,f_d) = \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\frac{1}{N^{d-m}} \sum\limits_{\mathbf{n} \in \mathbb{Z}^{d-u}} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j) \Big)F(\Xi(\mathbf{n}) + \widetilde{\mathbf{r}}) G(L\Xi(\mathbf{n}) + L\widetilde{\mathbf{r}}),
\end{equation}

