\sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\frac{1}{N^{d-m}} \sum\limits_{\mathbf{n} \in \mathbb{Z}^{d-u}} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j) \Big)F_{\widetilde{\mathbf{r}}}(\mathbf{n})G_{\widetilde{\mathbf{r}}}( \pi_{m-u} PL\Xi(\mathbf{n})).
\end{equation}

