L^\prime: = \pi_{m-u} PL\Xi.
\end{equation}

\begin{equation}
\label{funky dual basis}
\mathcal{B}^* := \{ \mathbf{x_i^*}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j})^*: j\leqslant d-u\}
\end{equation}

\begin{align}
\label{first approximation equation of part 8 of the lemma}
\operatorname{dist}(L^*(P^*\pi_{m-u}^*(\varphi)),(\mathbb{Z}^d)^T) \ll_{c,C}\eta;\\
\label{second approximation equation of part 8 of the lemma}
\Vert P^*\pi_{m-u}^*(\varphi)\Vert_\infty \ll_{c,C} \tau_2^{-1};\\
\label{third approximation equation of part 8 of the lemma}
\operatorname{dist}(P^*\pi_{m-u}^*(\varphi), \Theta^*((\mathbb{R}^{u})^*)) \gg_{c,C} \tau_1, 
\end{align}

\label{Lemma making G lipschitz}
Let $m,d,h$ be natural numbers, satisfying $d\geqslant h\geqslant m+1$. Let $c,C,\varepsilon$ be positive, and let $\sigma_G$ be any parameter in the range $0<\sigma_G<1/2$. Let $L^\prime:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a purely irrational surjective map, and let $\Xi:\mathbb{R}^{h} \longrightarrow \mathbb{R}^d$ be an injective map. Suppose that $\Vert L^\prime\Vert_\infty \leqslant C$ and that $\operatorname{dist}(L^\prime, V_{\operatorname{rank}}(m,h)) \geqslant c$. Let $F_{\widetilde{\mathbf{r}}}:\mathbb{R}^h \longrightarrow [0,1]$ be any function supported on $[-N,N]^h$, and let $G_{\widetilde{\mathbf{r}}}:\mathbb{R}^m \longrightarrow [0,1]$ be the indicator function of a convex set contained within $[-\varepsilon,\varepsilon]^m$. Then there exists a Lipschitz function $G_{\widetilde{\mathbf{r}}, \sigma_G,1}$ supported on $[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m}$, and with Lipschitz constant $O_{c,C,\varepsilon}(1/\sigma _G)$, such that, for any parameter $\tau_2$ in the range $0<\tau_2\leqslant 1$ and for any functions $f_1,\dots,f_d:[N] \longrightarrow [-1,1]$,
\begin{align*}
\vert &T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert \\ &\ll_{c,C,\varepsilon} \vert T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}},\sigma_G,1},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert + \sigma_G + \frac{\tau_2^{1/2}}{\sigma _G} +  \frac{\tau_2^{-O(1)}A_L(\Omega_{c,C}(1),\tau_2)^{-1}}{N}.
\end{align*}

Assume the hypotheses of Theorem \ref{Main Theorem chapter 3}. Let $\sigma_F$ and $\sigma_G$ be any parameters satisfying $0<\sigma_F,\sigma_G<1/2$, and let $\tau_2$ be any parameter satisfying $0<\tau_2\leqslant 1$. 

By Lemma \ref{Lemma replacing F cut-off}, \[\vert T_{F,G,N}^L(f_1,\dots,f_d)\vert \leqslant \vert T_{F_{1,\sigma_F},G,N}^L(f_1,\dots,f_d)\vert + O_{c,C}(\sigma_F),\] for some function $F_{1,\sigma_F}:\mathbb{R}^{d} \longrightarrow [0,1]$ supported on $[-2N,2N]^d$ and with Lipschitz constant $O(1/\sigma_F N)$. By part (4) of Lemma \ref{Lemma generating a purely irrational map}, writing $F_{1,\sigma_F}$ for $F$, we have \[\vert T_{F_{1,\sigma_F},G,N}^L(f_1,\dots,f_d)\vert  \leqslant \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\vert T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert, \] where the objects $F_{\widetilde{\mathbf{r}}}$, $G_{\widetilde{\mathbf{r}}}$, $L^\prime$, $\Xi$ and $\widetilde{R}$ satisfy all the conclusions of that lemma. \\


 Parts (1), (5) and (6) of Lemma \ref{Lemma generating a purely irrational map} show that $\Xi$ and $L^\prime$ satisfy the hypotheses of Lemma \ref{Lemma making G lipschitz}, where in the notation of Lemma \ref{Lemma making G lipschitz} we take $h: = d-u$ and rewrite $m$ for $m-u$. So, applying Lemma \ref{Lemma making G lipschitz}, there are some Lipschitz functions $G_{\widetilde{\mathbf{r}},\sigma_G,1}:\mathbb{R}^{m-u} \longrightarrow [0,1]$ supported on $[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m-u}$ and with Lipschitz constant $O_{c,C,\varepsilon}(1/\sigma_G)$ such that 
\begin{align}
&\vert T_{F,G,N}^L(f_1,\dots,f_d)\vert \nonumber \\
&\ll_{c,C,\varepsilon}  \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}\vert T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}},\sigma_G,1},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert + \sigma_G + \frac{\tau_2^{1/2}}{\sigma _G} +  \frac{\tau_2^{-O(1)}A_{L^\prime}(\Omega_{c,C}(1),\tau_2)^{-1}}{N} + \sigma_F.
\end{align}
\noindent (Recall that $\vert \widetilde{R}\vert = O_{c,C,\varepsilon}(1)$, by part (2) of Lemma \ref{Lemma generating a purely irrational map}.)

By conclusion (8) of Lemma \ref{Lemma generating a purely irrational map}, we may replace the term $A_{L^\prime}(\Omega_{c,C}(1),\tau_2)^{-1}$ with the term $A_{L}(\Omega_{c,C}(1),\Omega_{c,C}(\tau_2))^{-1}$. \\

Since $F_{\widetilde{\mathbf{r}}}$, $L^\prime$, $\Xi$, and $\widetilde{R}$ together satisfy conclusions (1), (2), (3), (6), and (7) of Lemma \ref{Lemma generating a purely irrational map}, the hypotheses are satisfied so that we may apply Theorem \ref{Theorem rational set out version} to the expression $T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}},\sigma_G,1},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)$. (We take $h = d-u$ and rewrite $m$ for $m-u$, as above). Therefore there exists an $s$ at most $d-2$, independent of $F_{\widetilde{\mathbf{r}}}$, $ G_{\widetilde{\mathbf{r}}}$ and $\widetilde{\mathbf{r}}$, such that, if \[ \min_j \Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho,\] for some $\rho$ in the range $0<\rho \leqslant 1$ then $\vert T_{F,G,N}^L(f_1,\dots,f_d)\vert$ is 

