\label{Lemma transfer equation}
Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon,\eta$ be positive constants. Let $\Xi:\mathbb{R}^h\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and assume that $\Xi(\mathbb{Z}^{h}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$. Let $L:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume that $\Vert \Xi \Vert_\infty \leqslant C$, $\Vert L \Vert_\infty \leqslant C$, and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,h)) \geqslant c$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$ with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a Lipschitz function supported on $[-\varepsilon,\varepsilon]^m$ with Lipschitz constant $O(1/\sigma_G)$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$. Let $\chi:\mathbb{R}\longrightarrow [0,1]$ be an $\eta$-supported measurable function. Then, if $\eta$ is small enough (in terms of the dimensions $m,d,h$, $C$, and $\varepsilon$) there exists some positive real number $C_{\Xi,\chi}$ such that, if $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ are arbitrary functions,
\begin{equation}
\label{eqn transfer equation}
T_{F,G,N}^{\Xi,L,\widetilde{\mathbf{r}}}(f_1,\dots,f_d) = \frac{1}{C_{\Xi,\chi}\eta^{h}}\widetilde{T}_{F,G,N}^{\Xi,L,\widetilde{\mathbf{r}}}(f_1\ast \chi,\dots,f_d\ast \chi) + O_{C,c,\varepsilon}(\eta/\sigma_G) + O_{C,c,\varepsilon}(\eta/\sigma_F N).
\end{equation}
\noindent Moreover, $C_{\Xi,\chi} \asymp_C 1$.

Let $\boldsymbol{\chi}:\mathbb{R}^d \longrightarrow [0,1]$ denote the function $\mathbf{x}\mapsto \prod\limits_{i=1}^d \chi(x_i)$. We choose \[ C_{\Xi,\chi} : = \frac{1}{\eta^h}\int\limits_{\mathbf{x} \in \mathbb{R}^h} \boldsymbol{\chi}(\Xi(\mathbf{x})) \, d\mathbf{x} .\] Since $\chi$ is $\eta$-supported, $C_{\Xi,\chi} \asymp_C 1$ . 

Then, expanding the definition of the convolution, \[\frac{1}{C_{\Xi,\chi}\eta^{h}}\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(f_1\ast \chi,\dots,f_d\ast \chi)\] equals
\begin{align}
\label{equation transferring zero}
&\frac{1}{N^{h-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^d}\Big(\prod\limits_{j=1}^d f_j(n_j)\Big) \frac{1}{C_{\Xi,\chi}\eta^h} \int\limits_{\mathbf{y}\in \mathbb{R}^h} F(\mathbf{y}) G(L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y})  + \widetilde{\mathbf{r}} - \mathbf{n}) \, d\mathbf{y}. 
\end{align}
Note that any vector $\mathbf{n} \in \mathbb{Z}^d$ that gives a non-zero contribution to expression (\ref{equation transferring zero}) satisfies $\Vert \mathbf{n} - \Xi(\mathbf{y}) - \widetilde{\mathbf{r}}\Vert_\infty \ll \eta$, for some $\mathbf{y} \in \mathbb{R}^h$. Therefore, $\mathbf{n}$ must be of the form $\Xi(\mathbf{n^\prime}) + \widetilde{\mathbf{r}}$ for some unique $\mathbf{n^\prime} \in\mathbb{Z}^h$. (This is proved in full in Lemma \ref{Lemma integer distance}). Therefore, writing $\Xi = (\xi_1,\dots,\xi_d)$, we may reformulate (\ref{equation transferring zero}) as
\begin{align}
&\frac{1}{N^{h-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^h} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j)\Big) \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in \mathbb{R}^h} F(\mathbf{y}) G(L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y}-\mathbf{n}))\, d\mathbf{y},\nonumber
\end{align}
\noindent which is equal to 
\begin{equation}
\label{extra equation to be referenced in transfer argument}
\frac{1}{N^{h-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^h} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j)\Big) \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in \mathbb{R}^h}  (F(\mathbf{n}) + O_C(\eta/\sigma_F N))G(L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y} - \mathbf{n})) \, d\mathbf{y}.
\end{equation}
Indeed, the inner integral is only non-zero when  $\Vert \Xi(\mathbf{y}) - \Xi(\mathbf{n})\Vert_\infty\ll\eta$, and this implies that $\Vert \mathbf{y} - \mathbf{n}\Vert_\infty \ll C^{-O(1)} \eta$. (This is proved in full in Lemma \ref{Lemma bounded inverse}). Then recall that $F$ has Lipschitz constant $O(1/\sigma_F N)$.\\

 Continuing, expression (\ref{extra equation to be referenced in transfer argument}) is equal to 
\begin{equation}
\label{equation transferring}
\frac{1}{N^{h-m}} \sum\limits_{\mathbf{n}\in\mathbb{Z}^h}\Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j)\Big) F(\mathbf{n}) H(L\mathbf{n} ) + E
\end{equation}
\noindent where \[H(\mathbf{x}) = \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in\mathbb{R}^h}  \boldsymbol{\chi}(\Xi(\mathbf{y}))G(\mathbf{x} + L\mathbf{y})\ \, d\mathbf{y}\] and $E$ is a certain error, that may be bounded above by 
\begin{equation}
\label{transfer error bounded above}
\ll_C \frac{\eta}{\sigma_F N} \frac{1}{N^{h-m}} \sum\limits_{\mathbf{n}\in[-O(N),O(N)]^h}H(L\mathbf{n}).
\end{equation}  

Let us deal with the first term of (\ref{equation transferring}), in which we wish to replace $H$ with $G$. We therefore consider
\begin{equation*}
\Big\vert\frac{1}{N^{h-m}} \sum\limits_{\mathbf{n}\in\mathbb{Z}^h}\Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j)\Big) F(\mathbf{n}) (G(L\mathbf{n}) - H(L\mathbf{n})) \Big\vert,
\end{equation*}
which is
\begin{equation}
\label{equation transferring main term differencing}
\leqslant \frac{1}{N^{h-m}} \sum\limits_{\mathbf{n}\in\mathbb{Z}^h}F(\mathbf{n}) \vert G-H\vert(L\mathbf{n}).
\end{equation} Using Lemma \ref{Lemma bounded inverse} again, the function $H$ is supported on $[-\varepsilon - O_C(\eta), \varepsilon + O_C(\eta)]^m$. Thus, if $\eta$ is small enough in terms of $\varepsilon$, the function $\vert G-H\vert:\mathbb{R}^m\longrightarrow \mathbb{R}$ is supported on $[-O_C(\varepsilon), O_C(\varepsilon)]^m$. Furthermore, $\Vert G - H\Vert_\infty = O_C(\eta/\sigma_G)$. Indeed, 
\begin{align*}
&G(\mathbf{x}) - \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in\mathbb{R}^h} G(\mathbf{x}+ L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y})) \, d\mathbf{y} \\
&= G(\mathbf{x}) - \frac{1}{C_{\Xi,\chi}\eta^h} \int\limits_{\mathbf{y} \in\mathbb{R}^h} (G(\mathbf{x}) + O_C(\eta/\sigma_G))\boldsymbol{\chi}(\Xi(\mathbf{y})) \, d\mathbf{y}\\
& = O_C(\eta/\sigma_G),\nonumber
\end{align*}
\noindent by the definition of $C_{\Xi,\chi}$ and using the Lipschitz property of $G$. So, by the crude bound given in Lemma \ref{Lemma crude bound on number of solutions}, (\ref{equation transferring main term differencing}) may be bounded above by $O_{c,C,\varepsilon}(\eta/\sigma_G)$. \\ 



Turning to the error $E$ from (\ref{equation transferring}), we've already remarked that it may be bounded above by expression (\ref{transfer error bounded above}). Applying Lemma \ref{Lemma crude bound on number of solutions} again, expression (\ref{transfer error bounded above}) may be bounded above by $O_{c,C,\varepsilon}(\eta/\sigma_F N)$. \\

Lemma \ref{Lemma transfer equation} follows immediately upon substituting the estimates on (\ref{transfer error bounded above}) and (\ref{equation transferring main term differencing}) into \eqref{equation transferring}.

\begin{align}
\label{equation transferring zero}
&\frac{1}{N^{h-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^d}\Big(\prod\limits_{j=1}^d f_j(n_j)\Big) \frac{1}{C_{\Xi,\chi}\eta^h} \int\limits_{\mathbf{y}\in \mathbb{R}^h} F(\mathbf{y}) G(L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y})  + \widetilde{\mathbf{r}} - \mathbf{n}) \, d\mathbf{y}. 
\end{align}

\begin{equation}
\label{extra equation to be referenced in transfer argument}
\frac{1}{N^{h-m}}\sum\limits_{\mathbf{n}\in \mathbb{Z}^h} \Big(\prod\limits_{j=1}^d f_j(\xi_j(\mathbf{n}) + \widetilde{\mathbf{r}}_j)\Big) \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in \mathbb{R}^h}  (F(\mathbf{n}) + O_C(\eta/\sigma_F N))G(L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y} - \mathbf{n})) \, d\mathbf{y}.
\end{equation}

\begin{align*}
&G(\mathbf{x}) - \frac{1}{C_{\Xi,\chi}\eta^h}\int\limits_{\mathbf{y}\in\mathbb{R}^h} G(\mathbf{x}+ L\mathbf{y}) \boldsymbol{\chi}(\Xi(\mathbf{y})) \, d\mathbf{y} \\
&= G(\mathbf{x}) - \frac{1}{C_{\Xi,\chi}\eta^h} \int\limits_{\mathbf{y} \in\mathbb{R}^h} (G(\mathbf{x}) + O_C(\eta/\sigma_G))\boldsymbol{\chi}(\Xi(\mathbf{y})) \, d\mathbf{y}\\
& = O_C(\eta/\sigma_G),\nonumber
\end{align*}

\label{Lemma linking different Gowers norms}
Let $s$ be a natural number, and assume that $\eta$ is a positive parameter that is small enough in terms of $s$. Let $\chi:\mathbb{R}\longrightarrow [0,1]$ be an $\eta$-supported measurable function. Let $N$ be a natural number, and let $f:[N]\longrightarrow \mathbb{R}$ be an arbtirary function. View $f\ast \chi$ as a function supported on $[-2N,2N]$. Then we have \begin{equation}
\label{linking different gowers norms}
\Vert f\ast \chi\Vert_{U^{s+1}(\mathbb{R},2N)}\ll \eta^{\frac{s+2}{2^{s+1}}} \Vert f\Vert_{U^{s+1}[N]}. 
\end{equation}

From expression (\ref{explicit real gowers norms}), we have $$\Vert f\ast \chi \Vert _{U^{s+1}(\mathbb{R},2N)}^{2^{s+1}} \ll \frac{1}{N^{s+2}}\int\limits_{(x,\mathbf{h})\in \mathbb{R}^{s+2}}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^{s+1}} (f\ast \chi)(x+ \mathbf{h}\cdot\boldsymbol{\omega}) \, dx\, d\mathbf{h}.$$ Substituting in the definition of $f\ast \chi$, this is equal to 
\begin{equation}
\label{comparing gowers norms equation}
\frac{1}{N^{s+2}} \sum\limits_{(n_{\boldsymbol{\omega}})_{\boldsymbol{\omega}\in \{0,1\}^{s+1}} \in \mathbb{Z}^{\{0,1\}^{s+1}}} \Big(\prod\limits_{\boldsymbol{\omega} \in\{0,1\}^{s+1}} f(n_{\boldsymbol{\omega}})\Big)\int\limits_{(x,\mathbf{h})\in \mathbb{R}^{s+2}} \boldsymbol{\chi}(\Psi(x,\mathbf{h}) - \mathbf{n}) \, dx \, d\mathbf{h}, 
\end{equation}
where $\Psi:\mathbb{R}^{s+2}\longrightarrow \mathbb{R}^{2^{s+1}}$ has coordinate functions $\psi_{\boldsymbol{\omega}}$, indexed by $\boldsymbol{\omega} \in \{0,1\}^{s+1}$, where $\psi_{\boldsymbol{\omega}}(x,\mathbf{h}) : = x + \mathbf{h} \cdot \boldsymbol{\omega}$. In similar notation to that used in the previous proof, for $\mathbf{x} \in \mathbb{R}^{2^{s+1}}$, we let $\boldsymbol{\chi}(\mathbf{x}) : = \prod_{i=1}^{2^{s+1}} \chi(x_i)$.  Note that $\Psi$ is injective, $\Psi(\mathbb{Z}^{s+2}) = \mathbb{Z}^{2^{s+1}} \cap \operatorname{im} \Psi$, and $\Vert \Psi\Vert_\infty = O_s(1)$.  

The contribution to the inner integral of (\ref{comparing gowers norms equation}) from a particular $\mathbf{n}$ is zero unless $\Vert \mathbf{n} - \Psi(x,\mathbf{h})\Vert_\infty \ll \eta$, for some $(x,\mathbf{h}) \in \mathbb{R}^{s+2}$. Therefore, if $\eta$ is small enough we can conclude that $\mathbf{n}$ must be of the form $\Psi(p,\mathbf{k})$, for some unique $(p,\mathbf{k}) \in \mathbb{Z}^{s+2}$. (To spell it out, apply Lemma \ref{Lemma integer distance} with the map $\Psi$ in place of the map $\Xi$). So (\ref{comparing gowers norms equation}) is equal to 
\begin{equation}
\frac{1}{N^{s+2}} \sum\limits_{(p,\mathbf{k}) \in \mathbb{Z}^{s+2}} \Big(\prod\limits_{\boldsymbol{\omega} \in \{0,1\}^{s+1}} f(p + \mathbf{k} \cdot \boldsymbol{\omega}) \Big) \int\limits_{(x,\mathbf{h})\in \mathbb{R}^{s+2}} \boldsymbol{\chi}(\Psi(x -p,\mathbf{h} - \mathbf{k})) \, dx \, d\mathbf{h}, 
\end{equation}
\noindent which, after a change of variables , is equal to 
\begin{equation}
\label{real gn becomes integer gn}
\frac{C}{N^{s+2}}\sum\limits_{(p,\mathbf{k})\in \mathbb{Z}^{s+2}}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^{s+1}} f(p+ \mathbf{k}\cdot\boldsymbol{\omega}),
\end{equation}
\noindent where \[C:=\int\limits_{(x,\mathbf{h})\in \mathbb{R}^{s+2}} \boldsymbol{\chi} (\Psi(x,\mathbf{h})) \, dx \, d\mathbf{h}.\] Since $\boldsymbol{\chi}$ has support contained within $[-\eta,\eta]^{2^{s+1}}$, a vector $(x,\mathbf{h})$ only makes a non-zero contribution to the above integral if $\Vert \Psi(x,\mathbf{h})\Vert_\infty \ll \eta$. This implies that $\Vert (x,\mathbf{h})\Vert_\infty \ll \eta$. (To prove this is full, apply Lemma \ref{Lemma bounded inverse} to the linear map $\Psi$). Since $\Vert \boldsymbol{\chi}\Vert_\infty = O(1)$, this means $C = O(\eta^{s+2})$. The lemma then follows from (\ref{real gn becomes integer gn}).

\label{Theorem Generalised von Neumann Theorem over reals}
Let $N,m,d,h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive reals. Let $\Xi = \Xi(N):\mathbb{R}^{h}\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and let $L = L(N):\mathbb{R}^d \longrightarrow\mathbb{R}^m$ be a surjective linear map. Suppose further that $\Vert L\Vert_\infty \leqslant C$, $\Vert \Xi\Vert_\infty \leqslant C$, $\operatorname{dist}( L,V_{\operatorname{rank}}(m,d)) \geqslant c$ and $\operatorname{dist} ((\Xi,L), V_{\operatorname{degen},2}^*(m,d,h))\geqslant c$. Then there is some natural number $s$ at most $d-2$, independent of $\varepsilon$, such that the following holds. Let $\widetilde{\mathbf{r}} \in \mathbb{Z}^d$ be some vector with $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$, and let $\sigma_F$ be a parameter in the range $O < \sigma_F < 1/2$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$, with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m} \longrightarrow [0,1]$ be any function supported on $[-\varepsilon, \varepsilon]^m$.  Let $g_1,\dots,g_d:[-2N,2N]^d\longrightarrow [-1,1]$ be arbitrary measurable functions. Suppose \[ \min\limits_{j\leqslant d}\Vert g_j\Vert_{U^{s+1}(\mathbb{R},2N)}\leqslant \rho\] for some $\rho$ at most $1$. Then 
\begin{equation}
\vert \widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \rho^{\Omega(1)}\sigma_F^{-1} 
\end{equation}
\noindent

 Assume the hypotheses of Theorem \ref{Theorem rational set out version}. This gives natural numbers $N,m,d,h$, linear maps $L:\mathbb{R}^h\longrightarrow \mathbb{R}^m$ and $\Xi:\mathbb{R}^h \longrightarrow \mathbb{R}^d$, and functions $F:\mathbb{R}^h \longrightarrow [0,1]$ and $G:\mathbb{R}^m \longrightarrow [0,1]$. Let $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ be arbitrary functions, and for ease of notation let \[\delta: = T _{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d).\] From Lemma \ref{Lemma crude bound on number of solutions} and the triangle inequality, we have the crude bound $\delta = O_{c,C,\varepsilon}(1)$. 

Let $\eta: = c_1\delta \sigma_G$, where $c_1$ is small enough depending on $m,d,h,c,C,$ and $\varepsilon$, and let $\chi: \mathbb{R}\longrightarrow [0,1]$ be an $\eta$-supported measurable function (see Definition \ref{Defintion eta supported}). For all $j$ at most $d$, let $g_j: = f_j\ast \chi$. Finally, suppose $\min _j \Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho$, for some parameter $\rho$ in the range $0<\rho \leqslant 1$.

We proceed by bounding $\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)$. Indeed, by Lemma \ref{Lemma linking different Gowers norms}, if $c_1$ is small enough \[\min_j\Vert g_j\Vert_{U^{s+1}(\mathbb{R})} \ll \eta^{\frac{s+2}{2^{s+1}}} \min_j\Vert f_j\Vert_{U^{s+1}[N]} \ll_{c,C,\varepsilon} \rho.\]  Applying Theorem \ref{Theorem Generalised von Neumann Theorem over reals} to these functions $g_1,\dots,g_d$, the above implies 
\begin{equation}
\label{extra extra}
\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\ll_{c,C,\varepsilon} \rho^{\Omega(1)} \sigma_F^{-1}.
\end{equation}

Now we use this to bound $\delta$ by Gowers norms. Indeed, by Lemma \ref{Lemma transfer equation}, we have 
\begin{align*}
\delta &\ll_{c,C,\varepsilon} \frac{1}{(c_1 \delta \sigma_G)^h}\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d) + c_1\delta + c_1\delta\sigma_G\sigma_F^{-1} N^{-1} .
\end{align*} 

Picking $c_1$ small enough, we may move the $c_1\delta$ term to the left-hand side to get an $\Omega(\delta)$ term. The bound (\ref{extra extra}) then yields
\begin{align*}
\delta^{h+1} \ll_{c,C,\varepsilon} \rho^{\Omega(1)} \sigma_F^{-1} \sigma_G^{-h} + \sigma_F^{-1} N^{-1},
\end{align*} 
and so \[ \delta \ll_{c,C,\varepsilon} \rho^{\Omega(1)} (\sigma_F^{-O(1)} + \sigma_G^{-O(1)}) + \sigma_F^{-O(1)}N^{-\Omega(1)}.\]  This yields the desired conclusion of Theorem \ref{Theorem rational set out version}.

\label{Proposition separating out the kernel}
Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive constants. Let $\sigma_F$ be a parameter in the range $0 <\sigma_F<1/2$. Let $\Xi:\mathbb{R}^h\rightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and let $L:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume further that $\Vert L \Vert_\infty \leqslant C$, $\Vert \Xi\Vert_\infty \leqslant C$, $\operatorname{dist}(L,V_{\operatorname{rank}}(m,h))\geqslant c$ and $\operatorname{dist} ((\Xi,L),V_{\operatorname{degen},2}^\ast (m,d,h)) \geqslant c$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[- CN,CN]^h$, with Lipschitz constant $O_C(1/\sigma_F N)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a measurable function supported on $[-\varepsilon,\varepsilon]^m$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{C}(1)$. Then there exists a system of linear forms $(\psi_1,\dots,\psi_d) = \Psi:\mathbb{R}^{h-m}\longrightarrow \mathbb{R}^d$ satisfying $\Vert \Psi\Vert_\infty = O_C(1)$, and a Lipschitz function $F_1:\mathbb{R}^{h-m}\longrightarrow [0,1]$ supported on $[-O_{c,C,\varepsilon}(N),O_{c,C,\varepsilon}(N)]^{h-m}$ with Lipschitz constant $O(1/\sigma_F N)$, such that, if $g_1,\dots,g_d:[-2N,2N]\longrightarrow [-1,1]$ are arbitrary functions, 
\begin{equation}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \Big\vert\frac{1}{N^{h-m}}\int\limits_{\mathbf{x}} \prod\limits_{j=1}^d g_j(\psi_j(\mathbf{x}) + a_j)F_1(\mathbf{x}) \, d\mathbf{x}\Big\vert ,
\end{equation}
\noindent where, for each $j$, $a_j$ is some real number that satisfies $a_j = O_{c,C,\varepsilon}(1)$.

Furthermore, there exists a natural number $s$ at most $d-2$ such that the system $\Psi$ has $\Omega_{c,C}(1)$-Cauchy-Schwarz complexity at most $s$, in the sense of Definition \ref{Definition Cauchy Schwarz complexity}.

For ease of notation, let 
\[ \beta: = \widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d).\]
Noting that $\ker L$ is a vector space of dimension $h-m$, define $\{\mathbf{v^{(1)}},\dots,\mathbf{v^{(h-m)}}\} \subset \mathbb{R}^h$ to be an orthonormal basis for $\ker L$. Then the map $\Phi:\mathbb{R}^{h-m} \longrightarrow \mathbb{R}^h$, defined by
\begin{equation}
\label{parametrise the kernel}
\Phi(\mathbf{x}) := \sum\limits_{i=1}^{h-m}x_i \mathbf{v}^{\mathbf{(i)}},
\end{equation}
\noindent is an injective map that parametrises $\ker L$. (This is reminiscent of Lemma \ref{Quantitative orthonormal basis parametrisation}). 



Now, extend the orthonormal basis $\{\mathbf{v^{(1)}},\dots,\mathbf{v^{(h-m)}}\}$ for $\ker L$ to an orthonormal basis $\{\mathbf{v^{(1)}},\dots,\mathbf{v^{(h)}}\}$ for $\mathbb{R}^h$. By implementing a change of basis, we may rewrite $\beta$ as
\begin{equation}
\label{separating out the kernel}
\frac{1}{N^{h-m}} \int\limits_{\mathbf{x}\in \mathbb{R}^h} F(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}})G(L(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}}))(\prod\limits_{j=1}^{d} g_j(\xi_j(\Phi(\mathbf{x_1^{h-m}})+\sum\limits_{i=h-m+1}^{h} x_i \mathbf{v}^{\mathbf{(i)}})+ \widetilde{\mathbf{r}}_j)) \, d\mathbf{x},
\end{equation}
\noindent using $\mathbf{x_1^{h-m}}$ to refer to the vector in $\mathbb{R}^{h-m}$ given by the first the first $h-m$ coordinates of $\mathbf{x}$.


We wish to remove the presence of the variables $x_{h-m+1},\dots,x_{h}$. To set this up, note that, by the choice of the vectors $\mathbf{v^{(i)}}$, $$G(L(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}})) = G(L(\sum\limits_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}})). $$ The vector $\sum_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}}$ is in $(\ker L)^{\perp}$. Hence, due to the limited support of $G$, there is a domain $D$, contained in $[-O_{\varepsilon,c,C}(1), O_{\varepsilon,c,C}(1)]^m$, such that \\$G(L(\sum_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}}))$ is equal to zero unless $(x_{h-m+1},\dots,x_h)^T\in D$. (This is proved in full in Lemma \ref{nonsingularity of map on orthogonal complement of Kernel}).

We can use this observation to bound the right-hand side of (\ref{separating out the kernel}). Indeed, we have 
\begin{align}
\label{equation bound beta by a sup}
\beta \ll \operatorname{vol} D \times \sup\limits_{\mathbf{x_{h-m+1}^h}\in D}\frac{1}{N^{h-m}} \Big\vert \int\limits_{\mathbf{x_{1}^{h-m}} \in \mathbb{R}^{h-m}} F(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}})G(L(\sum\limits_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}})) \nonumber\\
(\prod\limits_{j=1}^{d} g_j(\xi_j(\Phi(\mathbf{x_{1}^{h-m}})+\sum\limits_{i=h-m+1}^{h} x_i\mathbf{v}^{\mathbf{(i)}})+ \widetilde{\mathbf{r}}_j)) \, d \mathbf{x_1^{h-m}} \Big\vert.
\end{align} So there exists some fixed vector $(x_{h-m+1},\dots,x_h)^T$ in $D$ such that \begin{align}
\label{equation bound beta second}
\beta \ll_{c,C,\varepsilon}\frac{1}{N^{h-m}} \Big\vert \int\limits_{\mathbf{x_{1}^{h-m}} \in \mathbb{R}^{h-m}} &F(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}})G(L(\sum\limits_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}})) \nonumber\\
&(\prod\limits_{j=1}^{d} g_j(\xi_j(\Phi(\mathbf{x_{1}^{h-m}})+\sum\limits_{i=h-m+1}^{h} x_i\mathbf{v}^{\mathbf{(i)}})+ \widetilde{\mathbf{r}}_j)) \, d \mathbf{x_1^{h-m}} \Big\vert. 
\end{align}  

Define the function $F_1:\mathbb{R}^{h-m} \longrightarrow [0,1]$ by \[ F_1(\mathbf{x_1^{h-m}}) : = F(\Phi(\mathbf{x_1^{h-m}}) + \sum\limits_{i=h-m+1}^{h} x_i\mathbf{v^{(i)}})\] and for each $j$ at most $d$, a shift \[a_j :=\xi_j(\sum\limits_{i=h-m+1}^{h} x_i \mathbf{v}^{\mathbf{(i)}}) + \widetilde{\mathbf{r}}_j.\] Then
\begin{equation}
\label{just before we put everything into normal form}
\beta \ll _{c,C,\varepsilon}\Big\vert\frac{1}{N^{h-m}}\int\limits_{\mathbf{x} \in \mathbb{R}^{h-m}}F_1(\mathbf{x}) \prod\limits_{j=1}^d g_j(\xi_j(\Phi(\mathbf{x}))+a_j) \, d\mathbf{x}\Big\vert,
\end{equation} 
\noindent and $F_1$ and $a_j$ satisfy the conclusions of the proposition.

Finally, since $\operatorname{dist}((\Xi,L), V_{\operatorname{degen},2}^*(m,d,h)) \geqslant c$ and $\Vert \Xi\Vert_\infty, \Vert L\Vert_\infty \leqslant C$, Lemma \ref{Quantitative orthonormal basis parametrisation} tells us that $\Xi\Phi: \mathbb{R}^{h-m}\longrightarrow \mathbb{R}^d$ satisfies $\operatorname{dist}(\Xi\Phi, V_{\operatorname{degen}}(h-m,d))\gg_{c,C} 1$. (One may consult Definitions \ref{Definition degeneracy varieties} and Definition \ref{Definition dual pair degeneracy variety} for the definitions of $V_{\operatorname{degen}}(h-m,d)$ and $V_{\operatorname{degen},2}^*(m,d,h)$). Thus, by Lemma \ref{Lemma different forms of non degen}, there exists some $s$ at most $d-2$ for which $\Xi\Phi$ has $\Omega_{c,C}(1)$-Cauchy-Schwarz complexity at most $s$. 

Writing $\Psi$ for $\Xi\Phi$, the proposition is proved.

\begin{align}
\label{equation bound beta by a sup}
\beta \ll \operatorname{vol} D \times \sup\limits_{\mathbf{x_{h-m+1}^h}\in D}\frac{1}{N^{h-m}} \Big\vert \int\limits_{\mathbf{x_{1}^{h-m}} \in \mathbb{R}^{h-m}} F(\sum\limits_{i=1}^{h}x_i\mathbf{v^{(i)}})G(L(\sum\limits_{i=h-m+1}^{h}x_i\mathbf{v^{(i)}})) \nonumber\\
(\prod\limits_{j=1}^{d} g_j(\xi_j(\Phi(\mathbf{x_{1}^{h-m}})+\sum\limits_{i=h-m+1}^{h} x_i\mathbf{v}^{\mathbf{(i)}})+ \widetilde{\mathbf{r}}_j)) \, d \mathbf{x_1^{h-m}} \Big\vert.
\end{align}

\begin{equation}
\label{just before we put everything into normal form}
\beta \ll _{c,C,\varepsilon}\Big\vert\frac{1}{N^{h-m}}\int\limits_{\mathbf{x} \in \mathbb{R}^{h-m}}F_1(\mathbf{x}) \prod\limits_{j=1}^d g_j(\xi_j(\Phi(\mathbf{x}))+a_j) \, d\mathbf{x}\Big\vert,
\end{equation}

\label{Proposition Cauchy}
Let $s,d$ be natural numbers, with $d\geqslant 3$, and let $C$ be a positive constant. Let $\sigma_F$ be a parameter in the range $0 <\sigma_F<1/2$. Let $(\psi_1,\dots,\psi_d) = \Psi:\mathbb{R}^{s+1} \longrightarrow \mathbb{R}^d$ be a linear map, and suppose that $ \psi_1(\mathbf{e_k}) = 1$, for all the standard basis vectors $\mathbf{e_k} \in \mathbb{R}^{s+1}$. Suppose that, for all $j$ in the range $2\leqslant j\leqslant s+1$, there exists some $k$ such that $\psi_j(\mathbf{e_k}) = 0$. Let $N\geqslant 1$ be real, and let $g_1,\dots,g_d:[-N,N]\longrightarrow [-1,1]$ be arbitrary measurable functions, and, for each $j$ at most $d$, let $a_j$ be some real number with $\vert a_j\vert \leqslant CN$. Let $F:\mathbb{R}^{s+1} \longrightarrow [0,1]$ be any Lipschitz function, supported on $[-CN,CN]^{s+1}$ with Lipschitz constant $O(1/\sigma_F N)$. Suppose that $\Vert g_1 \Vert _{U^{s+1}(\mathbb{R},N)} \leqslant \rho$, for some parameter $\rho$ in the range $0<\rho\leqslant 1$. Then 
\begin{equation}
\label{equation abstract Gen von Neu}
\Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w}\in \mathbb{R}^{s+1}} \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)  F(\mathbf{w})\, d\mathbf{w}\Big\vert \ll_C \rho^{-\Omega(1)} \sigma_F^{-1}.
\end{equation}

\begin{equation}
\label{equation abstract Gen von Neu}
\Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w}\in \mathbb{R}^{s+1}} \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)  F(\mathbf{w})\, d\mathbf{w}\Big\vert \ll_C \rho^{-\Omega(1)} \sigma_F^{-1}.
\end{equation}

This theorem is very similar to the usual Generalised von Neumann Theorem (see \cite[Exercise 1.3.23]{Ta12}), and the proof is very similar too. A few extra technicalities arise from our dealing with the reals rather than with a finite group, but these are easily surmountable. 

We begin with some simple reductions. First, we assume that $C$ is large enough in terms of all other $O(1)$ parameters. For notational convenience, we will also allow $C$ to vary form line to line. Next, since $\psi_1(\mathbf{w}) = w_1+w_2+\cdots+w_{s+1}$, by shifting $w_1$ we can assume that $a_1 = 0$ in (\ref{equation abstract Gen von Neu}). Due to the restricted support of $F$, we may restrict the integral over $\mathbf{w}$ to $[-CN,CN]^{s+1}$. By Lemma \ref{Fourier transforms of Lipschitz functions}, for any $Y>2$ there is a function $\mathbf{c}_Y:\mathbb{R}^{s+1} \longrightarrow \mathbb{C}$ satisfying $\Vert \mathbf{c}\Vert_\infty \ll 1$ such that we may replace $F(\mathbf{w})$ by \[ \int\limits_{\substack{\mathbf{\boldsymbol{\theta}} \in \mathbb{R}^{s+1}\\ \Vert \boldsymbol{\theta} \Vert_\infty \leqslant Y}} c_Y(\boldsymbol{\theta})e(\frac{\boldsymbol{\theta}\cdot \mathbf{w}}{N}) \, d\boldsymbol{\theta} + O_C\left(\frac{\log Y}{\sigma_F Y}\right).\] We will determine a particularly suitable $Y$ later (which will depend on $\rho$). 

This means that \begin{align}
\label{after approximating Lipschitz}
&\Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w}\in \mathbb{R}^{s+1}} \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)  F(\mathbf{w})\, d\mathbf{w}\Big\vert \nonumber \\
& \ll \int\limits_{\substack{\boldsymbol{\theta} \in \mathbb{R}^{s+1}\\ \Vert \boldsymbol{\theta} \Vert_\infty \leqslant Y}} \Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w} \in \mathbb{R}^{s+1}}^*e(\frac{\boldsymbol{\theta}}{N}\cdot \mathbf{w}) \Big( \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)\Big) \, d\mathbf{w} \Big\vert \, d\boldsymbol{\theta} + O_C\left(\frac{\log Y}{\sigma_F Y}\right),
\end{align}
\noindent where $\int^*$ indicates the limits $\mathbf{w} \in [-CN,CN]^{s+1}$. Fix $\boldsymbol{\theta}$. The inner integral of (\ref{after approximating Lipschitz}) will be our primary focus. \\

Firstly, we wish to `absorb' the exponential phases $ e(\frac{\boldsymbol{\theta}}{N}\cdot \mathbf{w})$. To do this, we write $ e(\frac{\boldsymbol{\theta}}{N}\cdot \mathbf{w})$ as a product of functions $\prod_{k=1}^{s+1}b_k(\mathbf{w})$, where, for each $k$, the function $b_k:\mathbb{R}^{s+1}\longrightarrow \mathbb{C}$ is bounded in absolute value by $1$ and does not depend on the variable $w_k$. Since $s+1\geqslant 2$, this is possible. Now write \[ \prod\limits_{j=2}^d g_j(\psi_j(\mathbf{w}) + a_j) = \prod\limits_{k=1}^{s+1} b_k^\prime(\mathbf{w}),\] where each $b_k^\prime: \mathbb{R}^{s+1} \longrightarrow \mathbb{C}$ is bounded in absolute value by $1$ and does not depend on the variable $w_k$. This is possible since $\psi_1$ is the only function $\psi_j$ that includes all the variables $w_1,\dots,w_{s+1}$. 

Therefore we may rewrite the inner integral of (\ref{after approximating Lipschitz}) as 
\begin{equation}
\label{phases absorbed}
\frac{1}{N^{s+1}}\int\limits_{\mathbf{w} \in\mathbb{R}^{s+1}} ^*  g_1(\psi_1(\mathbf{w})) \prod\limits_{k=1}^{s+1} b_k^\prime(\mathbf{w}) b_k(\mathbf{w})\, d\mathbf{w}.
\end{equation}


A brief aside: readers familiar with the arguments of \cite[Appendix C]{GT10} (which motivate the present proof) may note that a different device is used in that paper to absorb the exponential phases. Those authors work in the setting of the finite group $\mathbb{Z}/N\mathbb{Z}$, and there the exponential phases can be absorbed simply by twisting the functions $g_j:\mathbb{Z}/N\mathbb{Z}\longrightarrow [-1,1]$ by a suitable linear phase function (witness the discussion surrounding expression (C.7) from \cite{GT10}). The key point there is that, if the linear form $\mathbf{w}\mapsto\boldsymbol{\theta}\cdot\mathbf{w}$ fails to be in the set $\operatorname{span}(\psi_j:1\leqslant j\leqslant d)$, then a Fourier expansion of $g_j$ demonstrates that a certain expression, analogous to the inner integral of (\ref{after approximating Lipschitz}), is equal to zero. This clean argument isn't quite so easy to apply here, as the linear phases are not integrable over all of $\mathbb{R}$, which is why we choose a different approach. \\

Returning to (\ref{phases absorbed}), recall that $\psi_1(\mathbf{w}) = w_1+w_2+\cdots + w_{s+1}$. Therefore, applying the Cauchy-Schwarz inequality in each of the variables $w_1$ through $w_{s+1}$ in turn, one establishes that the absolute value of expression (\ref{phases absorbed}) is at most 
\begin{equation}
\label{The box norm style Gowers norm expression}
\ll_C \Big(\frac{1}{N^{2s+2}}\int\limits_{\mathbf{w} \in\mathbb{R}^{s+1}}^* \int\limits_{\mathbf{z} \in\mathbb{R}^{s+1}}^* \prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}}g_1\Big(\sum\limits_{\substack{k\leqslant s+1\\ \boldsymbol{\alpha}_k = 0}}w_k + \sum\limits_{\substack{k\leqslant s+1\\ \boldsymbol{\alpha}_k = 1}}z_k \Big) \, d\mathbf{w}\, d\mathbf{z}\Big)^{\frac{1}{2^{s+1}}}.
\end{equation}


This expression may be immediately related to the real Gowers norm as given in Definition \ref{Definition of Gowers norms over R}, by the change of variables  $m_k:=z_k - w_k$, for all $k$ at most $s+1$, and $u: = w_1+\cdots+w_{s+1}$. Performing this change of variables shows that(\ref{The box norm style Gowers norm expression}) is 
\begin{equation}
\label{reparametrise to make look like Gowers norms}
\ll  \Big(\frac{1}{N^{2s+2}}\int\limits_{(u,\mathbf{m},\mathbf{z_2^{s+1}})\in D}\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m}) \, du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} \Big)^{\frac{1}{2^{s+1}}},
\end{equation}
\noindent where $D$ is convex domain contained within $[-CN,CN]^{2s+2}$. It remains to replace $D$ by a Cartesian box.  \\

By Lemma \ref{Lipschitz approximation of convex cutoffs} we may write \[ 1_D = F_{\sigma} + O(G_{\sigma}),\] for any $\sigma$ in the range $0<\sigma<1/2$, where $F_{\sigma},G_{\sigma}:\mathbb{R}^{2s+2} \longrightarrow [0,1]$ are Lipschitz functions supported on $[-CN,CN]^{2s+2}$, with Lipschitz constant $O_C(1/\sigma N)$, such that $\int_{\mathbf{x}} G_\sigma (\mathbf{x}) \, d\mathbf{x} = O_C(\sigma N^{2s+2})$. Then, since $\Vert g_1\Vert_\infty \leqslant 1$, we may bound (\ref{reparametrise to make look like Gowers norms}) above by 
\begin{equation}
\label{final gowers norm tweak}
 \Big(\frac{1}{N^{2s+2}}\int\limits_{u,\mathbf{m},\mathbf{z_2^{s+1}}}^{\ast} F_{\sigma}(u,\mathbf{m},\mathbf{z_2^{s+1}})\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m})  du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} + O_C(\sigma)\Big)^{\frac{1}{2^{s+1}}} ,
 \end{equation} where $\int^*$ now refers to the domain of integration $[-CN,CN]^{2s+2}$. 

By applying Lemma \ref{Fourier transforms of Lipschitz functions} to $F_\sigma$, for any $X>2$ the absolute value of expression (\ref{final gowers norm tweak}) is 
\begin{align}
\label{final removing lipschitz}
\ll_C\Big(\Big(&\frac{1}{N^{2s+2}} \int\limits_{\substack{\boldsymbol{\xi} \in \mathbb{R}^{2s+2}\\ \Vert\boldsymbol{\xi}\Vert_\infty \leqslant X}} \Big\vert \int\limits_{u,\mathbf{m},\mathbf{z_2^{s+1}}}^{\ast} e(\frac{\boldsymbol{\xi}}{N} \cdot  (u,\mathbf{m},\mathbf{z_2^{s+1}})) \nonumber \\ &\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m})  du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} \Big\vert \, d\boldsymbol{\xi} \Big)  + O(\sigma)+ O\Big(\frac{\log X}{\sigma X}\Big) \Big)^{\frac{1}{2^{s+1}}}.
\end{align}

Integrating over the variables $z_2,\dots,z_{s+1}$, and splitting the exponential phase amongst the different functions, expression (\ref{final removing lipschitz}) is 
\begin{align}
\label{nearly there!}
\ll_C \Big(\Big(\frac{1}{N^{s+2}}\int\limits_{\substack{\boldsymbol{\xi} \in \mathbb{R}^{2s+2}\\ \Vert\boldsymbol{\xi}\Vert_\infty \leqslant X}}\Big\vert \int\limits_{(u,\mathbf{m}) \in [-CN,CN]^{s+2}} \prod\limits_{\boldsymbol{\alpha} \in \{0,1\}^{s+1}} g_{\boldsymbol{\alpha}}(u+\boldsymbol{\alpha} \cdot \mathbf{m}) \, du \, d\mathbf{m} \Big\vert \, d\boldsymbol{\xi}\Big) \nonumber \\ + O_C(\sigma)+ O_C\Big(\frac{\log X}{\sigma X}\Big) \Big)^{\frac{1}{2^{s+1}}},
\end{align} where each function $g_{\boldsymbol{\alpha}}$ is of the form \[g_{\boldsymbol{\alpha}}(u) := g_1(u) e( k_{\boldsymbol{\alpha}} u)\] for some real $k_{\boldsymbol{\alpha}}$. Note that $\Vert g_{\boldsymbol{\alpha}} \Vert_{U^{s+1}(\mathbb{R},N)} = \Vert g_1 \Vert_{U^{s+1}(\mathbb{R},N)}$.

Recall that $g_1$ is supported on $[-2N,2N]$. Therefore, if $\prod_{\boldsymbol{\alpha} \in \{0,1\}^{s+1}} g_{\boldsymbol{\alpha}}(u+\boldsymbol{\alpha} \cdot \mathbf{m})\neq 0$ then $(u,\mathbf{m}) \in [-O(N),O(N)]^{s+2}$. So, if $C$ is large enough in terms of $s$, we may replace the restriction $(u,\mathbf{m}) \in [-CN,CN]^{s+2}$ in (\ref{nearly there!}) with the condition $(u,\mathbf{m}) \in \mathbb{R}^{s+2}$, without changing the value of (\ref{nearly there!}). 

Then, by the Gowers-Cauchy-Schwarz inequality (Proposition \ref{Proposition Gowers Cauchy Schwarz}) and the triangle inequality, (\ref{nearly there!}) is 
\begin{align}
\label{nearly nearly there!}
&\ll_C (X^{O(1)} \Vert g_1 \Vert_{U^{s+1}(\mathbb{R})}^{2^{s+1}} +  \sigma + \frac{\log X}{\sigma X} )^{\frac{1}{2^{s+1}}} \nonumber \\
&\ll_C (X^{O(1)} \rho ^{2^{s+1}} +  \sigma +  \frac{\log X}{\sigma X} )^{\frac{1}{2^{s+1}}} 
\end{align} Choosing $X = \rho^{-c_1}$, with $c_1$ suitably small in terms of $s$, and $\sigma = \rho^{c_1/2}$, expression (\ref{nearly nearly there!}) is $O_C(\rho^{\Omega(1)})$. \\


Putting this estimate into (\ref{after approximating Lipschitz}), we get a bound on (\ref{after approximating Lipschitz}) of 
\begin{equation}
\label{nearly nearly nearly there!!!}
\ll_C Y^{O(1)} \rho^{\Omega(1)}  + O(\frac{\log Y}{\sigma_F Y}).
\end{equation}
\noindent Picking $Y = \rho^{-c_1}$, with $c_1$ suitably small in terms of $s$, we may ensure that (\ref{nearly nearly nearly there!!!}) is $O_C(\rho^{\Omega(1)} \sigma_F^{-1})$, thus proving the proposition.

\begin{align}
\label{after approximating Lipschitz}
&\Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w}\in \mathbb{R}^{s+1}} \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)  F(\mathbf{w})\, d\mathbf{w}\Big\vert \nonumber \\
& \ll \int\limits_{\substack{\boldsymbol{\theta} \in \mathbb{R}^{s+1}\\ \Vert \boldsymbol{\theta} \Vert_\infty \leqslant Y}} \Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w} \in \mathbb{R}^{s+1}}^*e(\frac{\boldsymbol{\theta}}{N}\cdot \mathbf{w}) \Big( \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)\Big) \, d\mathbf{w} \Big\vert \, d\boldsymbol{\theta} + O_C\left(\frac{\log Y}{\sigma_F Y}\right),
\end{align}

\begin{equation}
\label{The box norm style Gowers norm expression}
\ll_C \Big(\frac{1}{N^{2s+2}}\int\limits_{\mathbf{w} \in\mathbb{R}^{s+1}}^* \int\limits_{\mathbf{z} \in\mathbb{R}^{s+1}}^* \prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}}g_1\Big(\sum\limits_{\substack{k\leqslant s+1\\ \boldsymbol{\alpha}_k = 0}}w_k + \sum\limits_{\substack{k\leqslant s+1\\ \boldsymbol{\alpha}_k = 1}}z_k \Big) \, d\mathbf{w}\, d\mathbf{z}\Big)^{\frac{1}{2^{s+1}}}.
\end{equation}

\begin{equation}
\label{reparametrise to make look like Gowers norms}
\ll  \Big(\frac{1}{N^{2s+2}}\int\limits_{(u,\mathbf{m},\mathbf{z_2^{s+1}})\in D}\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m}) \, du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} \Big)^{\frac{1}{2^{s+1}}},
\end{equation}

\begin{equation}
\label{final gowers norm tweak}
 \Big(\frac{1}{N^{2s+2}}\int\limits_{u,\mathbf{m},\mathbf{z_2^{s+1}}}^{\ast} F_{\sigma}(u,\mathbf{m},\mathbf{z_2^{s+1}})\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m})  du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} + O_C(\sigma)\Big)^{\frac{1}{2^{s+1}}} ,
 \end{equation}

\begin{align}
\label{final removing lipschitz}
\ll_C\Big(\Big(&\frac{1}{N^{2s+2}} \int\limits_{\substack{\boldsymbol{\xi} \in \mathbb{R}^{2s+2}\\ \Vert\boldsymbol{\xi}\Vert_\infty \leqslant X}} \Big\vert \int\limits_{u,\mathbf{m},\mathbf{z_2^{s+1}}}^{\ast} e(\frac{\boldsymbol{\xi}}{N} \cdot  (u,\mathbf{m},\mathbf{z_2^{s+1}})) \nonumber \\ &\prod\limits_{\boldsymbol{\alpha}\in \{0,1\}^{s+1}} g_1(u+\boldsymbol{\alpha}\cdot\mathbf{m})  du \, d\mathbf{m} \, d \mathbf{z_2^{s+1}} \Big\vert \, d\boldsymbol{\xi} \Big)  + O(\sigma)+ O\Big(\frac{\log X}{\sigma X}\Big) \Big)^{\frac{1}{2^{s+1}}}.
\end{align}

\begin{align}
\label{nearly there!}
\ll_C \Big(\Big(\frac{1}{N^{s+2}}\int\limits_{\substack{\boldsymbol{\xi} \in \mathbb{R}^{2s+2}\\ \Vert\boldsymbol{\xi}\Vert_\infty \leqslant X}}\Big\vert \int\limits_{(u,\mathbf{m}) \in [-CN,CN]^{s+2}} \prod\limits_{\boldsymbol{\alpha} \in \{0,1\}^{s+1}} g_{\boldsymbol{\alpha}}(u+\boldsymbol{\alpha} \cdot \mathbf{m}) \, du \, d\mathbf{m} \Big\vert \, d\boldsymbol{\xi}\Big) \nonumber \\ + O_C(\sigma)+ O_C\Big(\frac{\log X}{\sigma X}\Big) \Big)^{\frac{1}{2^{s+1}}},
\end{align}

\begin{align}
\label{nearly nearly there!}
&\ll_C (X^{O(1)} \Vert g_1 \Vert_{U^{s+1}(\mathbb{R})}^{2^{s+1}} +  \sigma + \frac{\log X}{\sigma X} )^{\frac{1}{2^{s+1}}} \nonumber \\
&\ll_C (X^{O(1)} \rho ^{2^{s+1}} +  \sigma +  \frac{\log X}{\sigma X} )^{\frac{1}{2^{s+1}}} 
\end{align}

\begin{equation}
\label{nearly nearly nearly there!!!}
\ll_C Y^{O(1)} \rho^{\Omega(1)}  + O(\frac{\log Y}{\sigma_F Y}).
\end{equation}

Assuming all the hypotheses of Theorem \ref{Theorem Generalised von Neumann Theorem over reals}, apply the result of Proposition \ref{Proposition separating out the kernel} to $\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)$. Thus 
\begin{equation}
\label{applying the first proposition chapter 3}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \Big\vert\frac{1}{N^{h-m}} \int\limits_{\mathbf{x} \in\mathbb{R}^{h-m}}  F_1(\mathbf{x})\prod\limits_{j=1}^d g_j(\psi_j(\mathbf{x}) +a_j) \, d\mathbf{x}\Big\vert,
\end{equation} where $\Psi: \mathbb{R}^{h-m} \longrightarrow \mathbb{R}^d$ has $\Omega_{c,C}(1)$-Cauchy-Schwarz complexity at most $s$, for some $s$ at most $d-2$, $F_1:\mathbb{R}^{h-m} \longrightarrow [0,1]$ is a Lipschitz function supported on $[-O_{c,C,\varepsilon}(N),O_{c,C,\varepsilon}(N)]^{h-m}$ with Lipschitz constant $O(1/\sigma_F N)$, and $a_j = O_{c,C,\varepsilon}(1)$. Furthermore $\Vert \Psi\Vert_\infty = O_C(1)$.

We apply Proposition \ref{normal form algorithm} to $\Psi$. Therefore, for \emph{any} real numbers $w_1,\dots,w_{s+1}$, 
\begin{equation}
\label{Fixed dummey variables}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert \ll \Big\vert \frac{1}{N^{h-m}}\int\limits_{\mathbf{x} \in \mathbb{R}^{h-m}}F_1(\mathbf{x} + \sum\limits_{k=1}^{s+1} w_k \mathbf{f_k})\prod\limits_{j=1}^d g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x}\Big\vert,
\end{equation}
\noindent where 
\begin{itemize}
\item for each $j$ at most $d$, $\psi^\prime_j:\mathbb{R}^{h-m} \times \mathbb{R}^{s+1}\longrightarrow \mathbb{R}$ is a linear form;
\item $\psi_1^\prime(\mathbf{0},\mathbf{w}) = w_1+\cdots+w_{s+1}$;
\item $\mathbf{f_1},\dots,\mathbf{f_{s+1}} \in \mathbb{R}^{h-m}$ are some vectors that satisfy $\Vert\mathbf{f_k}\Vert_\infty = O_{c,C}(1)$ for each $k$ at most $s+1$;
\item the system of forms $(\psi^\prime_1,\dots,\psi^\prime_d)$ is in normal form with respect to $\psi_1^\prime$. 
\end{itemize}
\noindent We remark that the right-hand side of expression (\ref{Fixed dummey variables}) is independent of $\mathbf{w}$, as it was obtained by applying the change of variables $\mathbf{x} \mapsto \mathbf{x} + \sum_{k=1}^{s+1} w_k\mathbf{f_k} $ to expression (\ref{applying the first proposition chapter 3}).\\

Now, let $P:\mathbb{R}^{s+1}\longrightarrow [0,1]$ be some Lipschitz function, supported on $[-N,N]^{s+1}$, with Lipschitz constant $O(1/N)$. Also suppose that $ P(\mathbf{x}) \equiv 1$ if $\Vert \mathbf{x}\Vert_\infty \leqslant N/2$. Integrating over $\mathbf{w}$, we have that $\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert$ is
\begin{align}
 &\ll_{c,C,\varepsilon}
\frac{1}{N^{h-m+s+1}} \int\limits_{\mathbf{w} \in \mathbb{R}^{s+1}} P(\mathbf{w}) \Big\vert\int\limits_{\mathbf{x}\in\mathbb{R}^{h-m}} F_1(\mathbf{x} + \sum\limits_{k=1}^{s+1} w_k \mathbf{f_k})\prod\limits_{j=1}^{d} g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x}\Big\vert \, d\mathbf{w} \nonumber \\
\label{equation after itnegrating over w}
 &\ll_{c,C,\varepsilon}\Big\vert\frac{1}{N^{h-m+s+1}} \int\limits_{\substack{\mathbf{x} \in \mathbb{R}^{h-m}\\ \mathbf{w} \in \mathbb{R}^{s+1}}} H(\mathbf{x},\mathbf{w}) \prod\limits_{j=1}^{d} g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x} \, d\mathbf{w}\Big\vert,
\end{align}
where the function $H:\mathbb{R}^{h-m+s+1} \longrightarrow [0,1]$ is defined by \[H(\mathbf{x},\mathbf{w}):= F_1(\mathbf{x} + \sum\limits_{k=1}^{s+1} w_k \mathbf{f_k}) P(\mathbf{w}). \] Since the vectors $\mathbf{f_k}$ satisfy $\Vert \mathbf{f_k}\Vert_\infty = O_{c,C}(1)$, $H$ is a Lipschitz function supported on $[-O_{c,C,\varepsilon} (N),O_{c,C,\varepsilon}(N)]^{h-m+s+1}$, with Lipschitz constant $O_{c,C}(1/\sigma_F N).$ Notice in (\ref{equation after itnegrating over w}) that we were able to move the absolute value signs outside the integral, as $P$ is positive and the integral over $\mathbf{x}$ is independent of $\mathbf{w}$ (so in particular has constant sign).

Fix $\mathbf{x}$. Then the integral over $\mathbf{w}$ in (\ref{equation after itnegrating over w}) satisfies the hypotheses of Proposition \ref{Proposition Cauchy}. Applying Proposition \ref{Proposition Cauchy} to this integral, and then integrating over $\mathbf{x}$, one derives \[\vert \widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert \ll_{c,C,\varepsilon} \rho^{\Omega(1)} \sigma_F^{-1}. \] Theorem \ref{Theorem Generalised von Neumann Theorem over reals} is proved.

\begin{equation}
\label{applying the first proposition chapter 3}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \Big\vert\frac{1}{N^{h-m}} \int\limits_{\mathbf{x} \in\mathbb{R}^{h-m}}  F_1(\mathbf{x})\prod\limits_{j=1}^d g_j(\psi_j(\mathbf{x}) +a_j) \, d\mathbf{x}\Big\vert,
\end{equation}

\begin{equation}
\label{Fixed dummey variables}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert \ll \Big\vert \frac{1}{N^{h-m}}\int\limits_{\mathbf{x} \in \mathbb{R}^{h-m}}F_1(\mathbf{x} + \sum\limits_{k=1}^{s+1} w_k \mathbf{f_k})\prod\limits_{j=1}^d g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x}\Big\vert,
\end{equation}

\begin{align}
 &\ll_{c,C,\varepsilon}
\frac{1}{N^{h-m+s+1}} \int\limits_{\mathbf{w} \in \mathbb{R}^{s+1}} P(\mathbf{w}) \Big\vert\int\limits_{\mathbf{x}\in\mathbb{R}^{h-m}} F_1(\mathbf{x} + \sum\limits_{k=1}^{s+1} w_k \mathbf{f_k})\prod\limits_{j=1}^{d} g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x}\Big\vert \, d\mathbf{w} \nonumber \\
\label{equation after itnegrating over w}
 &\ll_{c,C,\varepsilon}\Big\vert\frac{1}{N^{h-m+s+1}} \int\limits_{\substack{\mathbf{x} \in \mathbb{R}^{h-m}\\ \mathbf{w} \in \mathbb{R}^{s+1}}} H(\mathbf{x},\mathbf{w}) \prod\limits_{j=1}^{d} g_j(\psi_j^\prime(\mathbf{x},\mathbf{w}) + a_j) \, d\mathbf{x} \, d\mathbf{w}\Big\vert,
\end{align}

Recall the hypotheses of Theorem \ref{Converse to main theorem}. In particular, we suppose that $$\liminf\limits_{N\rightarrow\infty}\operatorname{dist}(L,V^*_{\operatorname{degen}}(m,d)) = 0,$$ i.e. we assume that $\operatorname{dist}(L,V_{\operatorname{degen}}^*(m,d)) = \omega(N)^{-1}$, for some function $\omega(N)$ such that $$\limsup_{N\rightarrow\infty} \omega(N) = \infty.$$  Let $\eta$ be a small positive quantity, picked small enough in terms of $c$ and $C$, and let $N$ be a natural number that is large enough so that $\omega(N)\geqslant \eta^{-1}$ and $\eta N\geqslant \operatorname{max}(1,\varepsilon)$. All implied constants to follow will be independent of $\eta$. 

Since $F$ is the indicator function of $[1,N]^d$ and $G$ is the indicator function of $[-\varepsilon,\varepsilon]^m$, one has \[T_{F,G,N}^L(f_1,\dots,f_d) = \frac{1}{N^{d-m}} \sum\limits_{\substack{\mathbf{n} \in [N]^d \\ \Vert L\mathbf{n} \Vert_\infty \leqslant \varepsilon}} \prod\limits_{j=1}^d f_j(n_j).\] Our aim is to construct functions $f_1,\dots,f_d:[N] \longrightarrow [-1,1]$ such that \[ \min_j\Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho\] for some $\rho$ at most $1$ and that \begin{equation}
\label{conclusion repeated}
T_{F,G,N}^L(f_1,\dots,f_d) > H(\rho) + E_\rho(N).
\end{equation} 

We begin by observing that the condition $\Vert L\mathbf{n}\Vert_\infty\leqslant \varepsilon$ implies certain constraints on two of the variables $n_i$. Indeed, let $L^\prime\in V_{\operatorname{degen}}^*(m,d)$ be such that $\Vert L - L^\prime \Vert_\infty = \operatorname{dist}(L,V_{\operatorname{degen}}^*(m,d))$. Write $\lambda_{ij}$ for the coefficients of $L$ and $\lambda_{ij}^\prime$ for the coefficients of $L^\prime$. By reordering columns, without loss of generality we may assume that there exist real numbers $\{a_i\}_{i=1}^m$ not all 0 s.t. for all $j$ in the range $3\leqslant j\leqslant d$ we have  
\begin{equation}
\label{all but 2 columns degenerate}
\sum\limits_{i=1}^m a_i \lambda^{\prime}_{ij} = 0,
\end{equation} and further we may assume that for all $i$ we have $\lambda^\prime_{i1} = \lambda_{i1}$ and $\lambda^\prime_{i2} = \lambda_{i2}$ (else $L^\prime\in V_{\operatorname{degen}}^*(m,d)$ is not one of the closest matrices to $L$). By reordering rows and rescaling, we may assume that $a_1$ has maximal absolute value amongst all the $a_i$, and that $\vert a_1\vert = 1$. 

Define $$b_1:=\sum\limits_{i=1}^m a_i \lambda_{i1}, \quad b_2:= \sum\limits_{i=1}^m a_i \lambda_{i2},$$ and let $\mathbf{n}\in [N]^d$ be some solution to $\Vert L\mathbf{n}\Vert_\infty \leqslant \varepsilon$. The critical observation is that (\ref{all but 2 columns degenerate}), combined with the assumptions on the $a_i$, implies that 
\begin{equation}
\label{the critical observation for construction}
\vert b_1 n_1 + b_2n_2\vert \ll \eta N.
\end{equation}  

Indeed, for $j$ in the range $3\leqslant j\leqslant d$ we have 
\begin{align*}
\left\vert\sum\limits_{i=1}^m a_i\lambda_{ij}\right\vert & = \left\vert\sum\limits_{i=1}^m a_i(\lambda_{ij} - \lambda^\prime_{ij})\right\vert \\
&\ll \eta.
\end{align*} 

\noindent Since $\Vert L\mathbf{n}\Vert_\infty \leqslant \varepsilon$, we certainly have that $$\left\vert b_1 n_1 + b_2n_2 + \sum\limits_{j=3}^d n_j\sum\limits_{i=1}^m a_i \lambda_{ij}\right\vert \ll \varepsilon,$$ and then (\ref{the critical observation for construction}) follows by the triangle inequality and the fact that $\eta N\geqslant \varepsilon$.\\

The constraint (\ref{the critical observation for construction}) will turn out to be enough for the proof. We consider various cases, constructing different counterexample functions $f_1$ and $f_2$ based on the size and sign of $b_1$ and $b_2$. To facilitate this, we let $c_1$ be a suitably small positive constant, depending on $c$ and $C$, but independent of $\eta$. All constants $C_1$ and $C_2$ to follow will be assumed to satisfy $C_1,C_2 = O_{c,C}(1)$. \\\\

\noindent \textbf{Case 1: $\vert b_1\vert,\vert b_2\vert \leqslant c_1$.}

Under the assumptions of Theorem \ref{Converse to main theorem}, this case is actually precluded. Indeed, consider the matrix $L^{\prime\prime}$, defined by taking $$\lambda_{ij}^{\prime\prime} = \lambda_{ij}^\prime$$ for all pairs $(i.j)\in [m]\times[d]$, except for $(1,1)$ and $(1,2)$. In these cases we let 
\begin{align*}
\lambda_{11}^{\prime\prime} &= \lambda_{11}^\prime - \frac{b_1}{a_1}\\
\lambda_{12}^{\prime\prime} & = \lambda_{12}^\prime - \frac{b_2}{a_1}.
\end{align*}
Then $$\sum\limits_{i=1}^m a_i\lambda_{ij}^{\prime\prime} = 0$$ for all $j$ in the range $1\leqslant j\leqslant d$. In other words we have shown that $\Vert L-L^{\prime\prime}\Vert_{\infty} \leqslant \eta + c_1$ for some matrix $L^{\prime\prime}$ with rank less than $m$. Since $\eta + c_1< c$ (if $c_1$ is small enough), this implies that $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d))<c$, which contradicts the assumptions of Theorem \ref{Converse to main theorem}. Therefore this case is indeed precluded. \\


\noindent \textbf{Case 2: $b_1,b_2$ both of the same sign, and $b_1,b_2\geqslant c_1$.}

In this case, (\ref{the critical observation for construction}) implies\footnote{The same conclusion is true for $n_2$, but this will not be needed.} that $n_1\leqslant C_1\eta N$ for some constant $C_1$. Now, define $f_1:[N]\longrightarrow [-1,1]$ to be the indicator function of the interval $[\lceil C_1\eta N\rceil, N]\cap \mathbb{N}$. We then have 
\begin{align*}
\Vert f_1 - 1\Vert_{U^{s+1}[N]} &\ll \Big(\frac{1}{N^{s+2}} \sum\limits_{x,h_1,\dots,h_{s+1}\ll C_1\eta N} 1\Big)^{\frac{1}{2^{s+1}}}\\
&\leqslant C_2(C_1\eta)^{\frac{s+2}{2^{s+1}}}
\end{align*}
\noindent for some constant $C_2$. However, observe that 
\begin{align*}
\vert T_{F,G,N}^L(f_1-1,1,\dots,1)\vert &= \vert T_{F,G,N}^L(f_1,1,\dots,1) - T_{F,G,N}^L(1,1,\dots,1)\vert\\
& = \vert 0 - T_{F,G,N}^L(1,1,\dots,1)\vert
\gg_{c,C,\varepsilon} 1
\end{align*}
\noindent by the hypotheses of Theorem \ref{Converse to main theorem}. If $T_{F,G,N}^L(f_1 - 1,1,\dots,1)$ did not satisfy (\ref{conclusion repeated}), then $$1 \ll_{c,C,\varepsilon} H(\rho) + E_{\rho}(1),$$ where $\rho := C_2(C_1\eta)^{\frac{s+2}{2^{s+1}}}$. Picking $\eta$ small enough, then $N$ large enough, this inequality cannot possibly hold, and we have a contradiction. So $T_{F,G,N}^L(f_1 - 1,1,\dots,1)$ satisfies (\ref{conclusion repeated}). \\

\noindent \textbf{Case 3: $b_1,b_2$ of opposite signs, and $b_1,b_2\geqslant c_1$.}

This is the most involved case, although the central idea is very simple. The condition (\ref{the critical observation for construction}) confines $n_2$ to lie within a certain distance of a fixed multiple of $n_1$. By constructing functions $f_1$ and $f_2$ using random choices of blocks of this length, but coupled in such a way that condition (\ref{the critical observation for construction}) is very likely to hold, we can guarantee that $T_{F,G,N}^L(f_1-p,f_2-p,1,\dots,1)$ is bounded away from zero, where $p$ is the probability used to choose the random blocks. However, despite the block construction and the coupling, the functions $f_1$ and $f_2$ still individually exhibit enough randomness to conclude that $\Vert f_1 - p\Vert _{U^{s+1}[N]} = o(1)$ as $N\rightarrow \infty$, and the same for $f_2$.  \\

We now fill in the technical details. Relation (\ref{the critical observation for construction}) implies that 
\begin{equation}
\label{the critical equation for construction with an explicit constant}
 \vert b_1n_1 + b_2n_2\vert \leqslant C_1\eta N,
\end{equation}
\noindent for some $C_1$ satisfying $C_1 = O(1)$, and without loss of generality assume that $b_1$ is positive, $b_2$ is negative, and $\vert b_1\vert$ is at least $\vert b_2\vert$. Let $C_2$ be some parameter, chosen so that $(C_1C_2\eta)^{-1}$ is an integer. Such a $C_2$ will of course depend on $\eta$, but in magnitude we may pick $C_2\asymp 1$. We consider the real interval $[0,N]$ modulo $N$, and for $x\in [0,N]$ and $i$ in the range $0\leqslant i\leqslant (C_1C_2\eta)^{-1} - 1$ we define the half-open interval modulo $N$ $$I_{x,i}: = [x+ i C_1C_2\eta N,x+(i+1)C_1C_2\eta N).$$  This choice guarantees that 
\begin{equation}
\label{the defining partition}
[0,N] = \bigcup\limits_{i=0}^{(C_1C_2\eta)^{-1} - 1} I_{x,i},
\end{equation}
 and the union is disjoint. Now, for $\delta$ a small constant to be chosen later\footnote{This $\delta$ is unrelated to the notation $\delta = T_{F,G,N}^L(f_1,\dots,f_d)$ used in previous sections.}, we define $$I^\delta_{x,i}: = [x+ (i+\frac{1}{2}-\delta) C_1C_2\eta N,x+(i+\frac{1}{2}+\delta)C_1C_2\eta N).$$ 

We will use the partition (\ref{the defining partition}) to construct a function $f_1$, using an averaging argument to choose an $x$ so that the $I_{x,i}^\delta$ intervals capture a positive proportion of the solution density of the linear inequality system. Indeed, for $n_1\in [N]$ let the weight $u(n_1)$ denote the number of $d-1$-tuples $n_2,\dots,n_d\leqslant N$ that together with $n_1$ satisfy the inequality $\Vert L\mathbf{n}\Vert_\infty < \varepsilon$. The weight $u(n_1)$ could be zero, of course. Let \[E_{x,\delta} := \cup_i I_{x,i}^\delta.\] Then
\begin{align*}
\frac{1}{N}\int\limits_{0}^N \sum\limits_{n\in [N]} u(n) 1_{E_{x,\delta}}(n) \, dx & = \frac{1}{N}\sum\limits_{n\in [N]} u(n)\int\limits_{0}^N 1_{E_{x,\delta}}(n)\, dx  \\
& = \sum\limits_{n\in [N]} u(n) 2\delta \\
& = 2\delta N^{d-m}T_{F,G,N}^L(1,\dots,1)
\end{align*}
\noindent Therefore, by the assumptions of Theorem \ref{Converse to main theorem}, we may fix an $x$ such that 
\begin{equation}
\label{capturing solutions in intervals}
\sum\limits_{n\in [N]} u(n) 1_{E_{x,\delta}}(n) \gg_{c,C} \delta N^{d-m}T_{F,G,N}^L(1,\dots,1).
\end{equation} 

Let us finally define the function $f_1$. Let $p$ be a small positive constant (to be decided later). Fix a value of $x$ such that (\ref{capturing solutions in intervals}) holds. Then we define a random subset $A\subseteq[N]$ by picking all of $I_{x,i} \cap \mathbb{N}$ to be members of $A$, with probability $p$, or none of $I_{x,i} \cap \mathbb{N}$ to be members of $A$, with probability $1-p$. We then make this same choice for each $i$ in the range $0\leqslant i \leqslant (C_1C_2\eta)^{-1} - 1$, independently. Observe immediately that for each $n\in [N]$ the probability that $n\in A$ is always $p$ (though these events are not always independent). We let $f_1(n)$ be the indicator function $1_A(n)$. 

The function $f_2$ is defined in terms of $f_1$. Indeed, let $$J_{x,i} = \frac{b_1}{\vert b_2\vert} I_{x,i}\cap (0,N],$$ where the dilation of the interval $I_{x,i}$ is not considered modulo $N$ but rather just as an operator on subsets of $\mathbb{R}$ (see Section \ref{Section Notation} for this notation). Since $b_1\geqslant \vert b_2\vert$ we have that these $J_{x,i}$ also form a disjoint partition of $[0,N]$. [NB: If $b_1>\vert b_2\vert$ it may be that certain $J_{x,i}$ are empty, since the dilate of the corresponding $I_{x,i}$ may land entirely outside $[0,N]$.] Then let $B$ be the subset of $[N]$ defined so that for each $i$ with $J_{x,i}$ non-empty we have $J_{x,i}\cap \mathbb{N}\subseteq B$ if and only if $I_{x,i}\cap \mathbb{N}\subseteq A$. Note again that for each individual $n\in [N]$ the probability that $n\in B$ is always $p$. We let $f_2(n)$ be the indicator function $1_B(n)$. \\

Our first claim is that, if $p$ is small enough in terms of $\delta$, 
\begin{equation}
\label{lower bound on solution count of coupled random sets}
\vert \mathbb{E} T_{F,G,N}^L(f_1,f_2,1,\dots,1)-T_{F,G,N}^L(p,p,1,\dots,1)\vert \gg_{c,C,\varepsilon} \delta^2.
\end{equation} Indeed, suppose that $I_{x,i}$ is included in the set $A$, and suppose that $n_1\in I_{x,i}^\delta$. If $n_2\in [N]$ satisfies $\vert \frac{b_1}{\vert b_2\vert} n_1 - n_2\vert \leqslant \frac{1}{b_2}C_1\eta N$ and if $\delta$ is small enough in terms of $b_1$ and $b_2$, then\footnote{This fact is the reason why we introduced the parameter $\delta$.} $n_2 \in J_{x,i}$. Thus, by the observation (\ref{the critical equation for construction with an explicit constant}), $n_2 \in B$, for every integer $n_2$ that is the second coordinate of a solution vector\footnote{i.e a vector $\mathbf{n}$ such that $\Vert L\mathbf{n}\Vert_\infty \leqslant \varepsilon$.} $\mathbf{n}$ for which the first coordinate is $n_1$. Therefore
\begin{align*}
\mathbb{E}T_{F,G,N}^L(f_1,f_2,1,\dots,1)& = \frac{1}{N^{d-m}}\sum\limits_{\substack{\mathbf{n}\in [N]^d \\ \Vert L\mathbf{n}\Vert_{\infty} \leqslant\varepsilon}} \mathbb{P}(n_1\in A\wedge n_2\in B)\\
&\geqslant \frac{1}{N^{d-m}}\sum\limits_{\substack{\mathbf{n}\in [N]^d \\ \Vert L\mathbf{n}\Vert_{\infty} \leqslant \varepsilon}} \mathbb{P}(n_1\in A \wedge n_1 \in I_{x,i}^\delta \text{ for some } i \wedge n_2\in B)\\
&\geqslant \frac{1}{N^{d-m}}\sum\limits_{\substack{\mathbf{n}\in [N]^d \\ \Vert L\mathbf{n}\Vert_{\infty} \leqslant \varepsilon}} \mathbb{P}(n_1\in A \wedge n_1 \in I_{x,i}^\delta \text{ for some } i)\\
& = \frac{1}{N^{d-m}}\sum\limits_{n_1\in [N] } u(n_1)p1_{E_{x,\delta}}
(n_1)\\
&\geqslant 2\delta p  T_{F,G,N}^L(1,\dots,1),
\end{align*}
\noindent where the final line follows from (\ref{capturing solutions in intervals}). On the other hand $T_{F,G,N}^L(p,p,1,\dots,1) = p^2T_{F,G,N}^L(1,\dots,1)$, and hence 
\begin{equation}
\mathbb{E} T_{F,G,N}^L(f_1,f_2,1,\dots,1)-T_{F,G,N}^L(p,p,1,\dots,1)\geqslant (2\delta p - p^2)T_{F,G,N}^L(1,\dots,1).
\end{equation}
Picking $p$ small enough in terms of $\delta$, and using the assumption that $T_{F,G,N}^L(1,\dots,1)  = \Omega_{c,C,\varepsilon}(1)$, this proves the relation (\ref{lower bound on solution count of coupled random sets}). \\

Our second claim is that 
\begin{equation}
\label{equatoin bound on expectation of gowers norms}
\mathbb{E}\Vert f_1 - p\Vert_{U^{s+1}[N]},\mathbb{E}\Vert f_2 - p\Vert_{U^{s+1}[N]} \ll \eta^{\frac{1}{2^{s+1}}}.
\end{equation} We first consider $f_1$. Then $$\mathbb{E}\Vert f_1 - p\Vert_{U^{s+1}[N]}^{2^{s+1}} \ll \frac{1}{N^{s+2}}\sum\limits_{\substack(x,\mathbf{h})\in \mathbb{Z}^{s+2}}\\ \mathbb{E}\Big(\prod\limits_{\boldsymbol{\omega} \in \{0,1\}^{s+1}} (f_1 - p1_{[N]})(x+\mathbf{h}\cdot\boldsymbol{\omega})\Big).$$ Observe that for fixed $(x,\mathbf{h})$ the random variables $(f_1 - p1_{[N]})(x+\mathbf{h}\cdot\boldsymbol{\omega})$ each have mean zero and, unless some two of the expressions $x+\mathbf{h}\cdot\boldsymbol{\omega}$ lie in the same block $I_i$, these random variables are independent. Hence, apart from those exceptional cases, we may factor the expectation and conclude that $$\mathbb{E}\Big(\prod\limits_{\boldsymbol{\omega} \in \{0,1\}^{s+1}} (f_1 - p1_{[N]})(x+\mathbf{h}\cdot\boldsymbol{\omega})\Big) = \prod\limits_{\boldsymbol{\omega} \in \{0,1\}^{s+1}} \mathbb{E}((f_1 - p1_{[N]})(x+\mathbf{h}\cdot\boldsymbol{\omega})) = 0.$$ Therefore,
\begin{align*}
\mathbb{E}\Vert f_1 - p\Vert_{U^{s+1}[N]}^{2^{s+1}}&\ll\frac{1}{N^{s+2}} \sum\limits_{(x,\mathbf{h})\in [-N,N]^{s+2}} 1_R(\mathbf{h})\\
&\ll \eta,
\end{align*}
