\label{Definition of Gowers norms over cyclic groups}
Let $N$ be a natural number. For a function $f:\mathbb{Z}/N\mathbb{Z}\longrightarrow \mathbb{C}$, and a natural number $d$, we define the Gowers $U^{d}$ norm $\Vert f\Vert_{U^{d}(N)}$ to be the unique non-negative solution to 
\begin{equation}
\label{Definition of Gowers norms}
\Vert f\Vert_{U^{d}(N)}^{2^d} = \frac{1}{N^{d+1}}\sum\limits_{x,h_1,\dots,h_d}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} f(x+\mathbf{h}\cdot\boldsymbol{\omega}),
\end{equation}
\noindent where $\vert \boldsymbol{\omega}\vert = \sum\limits_i \omega_i$, $\mathbf{h} = (h_1,\dots,h_d)$, $\mathcal{C}$ is the complex-conjugation operator, and the summation is over $x,h_1,\dots,h_d\in \mathbb{Z}/N\mathbb{Z}$.

\label{Definition of gowers norms over integers}
Let $N,N^\prime$ be natural numbers, with $N^\prime\geqslant N$. Identify $[N]$ with a subset of $\mathbb{Z}/N^\prime\mathbb{Z}$ in the natural way, i.e. $[N] = \{1,\dots,N\} \subseteq \{1,\dots,N^\prime\}$, which we then view as $\mathbb{Z}/N^\prime\mathbb{Z}$. For a function $f:[N]\longrightarrow \mathbb{C}$, and a natural number $d$, we define the Gowers norm $\Vert f\Vert_{U^d[N]}$ to be the unique non-negative real solution to the equation
\begin{equation}
\label{Definintion of gowers norms over integers the actual equation}
\Vert f\Vert_{U^d[N]} ^{2^d} = \frac{1}{\vert R\vert}\sum\limits_{x,h_1,\dots,h_d}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} f1_{[N]}(x+\mathbf{h}\cdot\boldsymbol{\omega}),
\end{equation}
\noindent where $f1_{[N]}$ is the extension by zero of $f$ to $\mathbb{Z}/N^\prime\mathbb{Z}$, the summation is over\\ $x,h_1,\dots,h_d\in \mathbb{Z}/N^\prime\mathbb{Z}$, and the set $R$ is the set $$R:=\{x,h_1,\dots,h_d\in \mathbb{Z}/N^\prime\mathbb{Z}: \text{ for every } \boldsymbol{\omega}\in \{0,1\}^d, x+\mathbf{h}\cdot\boldsymbol{\omega}\in [N]\}.$$

\begin{equation}
\label{Definintion of gowers norms over integers the actual equation}
\Vert f\Vert_{U^d[N]} ^{2^d} = \frac{1}{\vert R\vert}\sum\limits_{x,h_1,\dots,h_d}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} f1_{[N]}(x+\mathbf{h}\cdot\boldsymbol{\omega}),
\end{equation}

\begin{equation}
\label{comparing GN over ints with obvious sum}
\Vert f\Vert_{U^d[N]} \asymp \left( \frac{1}{N^{d+1}}\sum\limits_{x,h_1,\dots,h_d\in \mathbb{Z}}\prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} f(x+\mathbf{h}\cdot\boldsymbol{\omega})\right)^{\frac{1}{2^d}}.
\end{equation}

\label{Definition of Gowers norms over R}
Let $f:[0,1]\longrightarrow {\mathbb{C}}$ be a bounded measurable function, and let $d$ be a natural number. Then we define the Gowers norm $\Vert f \Vert_{U^{d}(\mathbb{R})}$ to be the unique non-negative real satisfying 

\begin{equation}
\Vert f \Vert_{U^{d}(\mathbb{R})}^{2^{d}} = \int\limits_{(x,\mathbf{h}) \in\mathbb{R}^{d+1}} \prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} f(x+\sum\limits_{i=1}^d h_i\omega_i) \, dx\,dh_1\cdots dh_d
\end{equation} 

\noindent where $\vert \boldsymbol{\omega}\vert = \sum\limits_i \omega_i$, and $\mathcal{C}$ is the complex-conjugation operator.

Define the function $f:[0,1]\longrightarrow \mathbb{C}$ by $f(x): = g(2Nx - N)$, and then set $$\Vert g\Vert_{U^d(\mathbb{R},N)}: = \Vert f\Vert_{U^d(\mathbb{R})}.$$ Explicitly, a change of variables shows that \begin{equation}
\label{explicit real gowers norms}
\Vert g \Vert_{U^{d}(\mathbb{R},N)}^{2^{d}} \asymp \frac{1}{N^{d+1}}\int\limits_{(x,\mathbf{h}) \in\mathbb{R}^{d+1}} \prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} g(x+\sum\limits_{i=1}^d h_i\omega_i) \, dx\,dh_1\cdots dh_d.

\begin{equation}
\label{explicit real gowers norms}
\Vert g \Vert_{U^{d}(\mathbb{R},N)}^{2^{d}} \asymp \frac{1}{N^{d+1}}\int\limits_{(x,\mathbf{h}) \in\mathbb{R}^{d+1}} \prod\limits_{\boldsymbol{\omega}\in \{0,1\}^d}\mathcal{C}^{\vert \boldsymbol{\omega} \vert} g(x+\sum\limits_{i=1}^d h_i\omega_i) \, dx\,dh_1\cdots dh_d.
\end{equation}

